quests[12483] = { id = 12483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shimmercap Stew", description = "Say, while yer here, how bout ya help ol' Prigmon with a little chore? I got a friend who can make a mean stew - one like ya never tasted before!\n\nThere be a few ingredients found in these parts that he be needin'. They be in ruins to the southwest and the camp just north o' here.\n\nWhatd'ya say, mon?", progress = "You get those ingredients for 'ol Prigmon, {name}?", completion = "Oh, mon - shimmercap stew! I can almost taste it already....", objectives = "Prigmon in Granite Springs wants you to collect 5 Shimmering Snowcaps and 5 Ice Serpent Eyes from Drak'Zin Ruins and 5 Sweetroot from Zeb'Halak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12484] = { id = 12484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourgekabob", description = "Ugh.\n\nWrappin' up these unfortunate trolls be makin' my heart ache, but not so much as my back!\n\nHelp ol' Prigmon out and haul one of these carcasses over to Mack.\n\nIf we don't burn 'em they be walkin' again in no time.", progress = "Whatcha got there, {race}?", completion = "Nothin' better than watchin' them shcourge burn... <hic>.\n\nWrote a little shong about it. Wanna hear it? Here goes....", objectives = "Prigmon at Granite Springs wants you to bring a Mummified Troll Carcass to Mack Fearsen and place it in the fire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12485] = { id = 12485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Howling Fjord: aa - A - LK FLAG" }
quests[12486] = { id = 12486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Bor'gorok Outpost, Quickly!", description = "Did you feel it?\n\n<Sauranok momentarily clutches his chest in confusion. His hand comes away trailing red-hot steam.>\n\nSomething terrible has happened to my old friend, Farseer Grimwalker. I just sensed it.\n\nHe had a pupil that he took with him when he went north. They were going to help the overlord establish an outpost on the edge of Sholazar Basin.\n\nHer name is Snarlfang. She is a spirit talker.\n\nPerhaps she will know what happened. Or, at least, she can help you to find out.", completion = "The mystic knows? You say he felt that something horrible happened to Farseer Grimwalker?\n\nIt is as I feared!", objectives = "Speak with Spirit Talker Snarlfang at Bor'gorok Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12487] = { id = 12487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Conquest Hold, But Be Careful!", description = "I've received a request for help from our base in the Grizzly Hills. I'm sending you to see Conqueror Krenna.\n\n<The high executor waves a sheaf of parchment in the air as if he could care less what is written on it.>\n\nShe's attempting to secure all of the natural resources or somesuch. Just watch your back around her. The word is that she's aggressive even for an orc.\n\nFollow the road east and then southeast. Cross the bridge at the Dragonspine Tributary and go east from the Evergreen Trading Post.", completion = "Who are you?\n\nTell me why I shouldn't split you in two where you stand!", objectives = "Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12488] = { id = 12488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Executor Needs You", description = "It's a good thing that I intercepted this request from High Executor Wroth before it got to Overlord Agmar. What is Wroth thinking?\n\n<The sergeant rips up the letter that he's holding.>\n\n{class}, go see what it is that the high executor wants.\n\nFollow the road east and pass through The Dragon Wastes. You'll find a path leading up out of the wastes on the southeast side, and the Forsaken town, Venomspite, will stand before you on the south side of the mountain.", completion = "You were sent from Agmar's Hammer? It's about time!\n\nNo, the help is not for me. I simply have no one else to spare, but you'll do.", objectives = "Speak with High Executor Wroth at Venomspite in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12489] = { id = 12489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Sholazar Basin", description = "So, where did you come from? I don't suppose that fool of an archmage sent you, too?\n\nYou're lucky to be in one piece, <laddie/lass>! They nearly blew you up!\n\nThe jungle here's a darned dangerous place, 'specially with the Venture Company about.\n\n Git you! Go see the boss... he'll sort you out. The camp's at the end of that path to the northwest.\n\nNow, git!", completion = "Hah! It's not often you run into a complete stranger in the middle of the jungle.\n\nYou one those druid lackeys sent to \"stop me and my evil ways?\" Yeah, good luck with that one!\n\n<Hemet lets out a hearty laugh and pats his gun.>\n\nDidn't think so! You're more than welcome to join us in the hunt, soon as we've dealt with those Venture Company dogs. There'll be plenty to go around.", objectives = "Follow the path to the northwest to reach the camp that Monte mentioned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12490] = { id = 12490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veehja's Revenge", description = "We share a common enemy today, {race}!  My people have been wiped out by these Kvaldir... my city has been all but destroyed.  It is time for exacting revenge!\n\nIn return for my help, I'd like you to slay the barbaric monsters that defile Riplash.  You will be well rewarded, {class}.", objectives = "Veehja at the Shrine of Scales wants you to slay 6 Skadir Mariners, 3 Skadir Mistweavers and 2 Skadir Runecasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12491] = { id = 12491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbrew's Dire Brew", description = "Coren Direbrew's corpse clutched this small cask tightly to its gut.  This must be his infamous Dire Brew!", progress = "{name}, your face has a grim set to it.  Do you have dire news?", completion = "This is the Coren Direbrew's drink?  The brew he wanted more than anything to submit at Brewfest?  Well, officially we can't recognize this submission, but out of respect for a fallen brewer, perhaps I'll have a taste...", objectives = "Give Direbrew's Dire Brew to Ipfelkofer Ironkeg at the Brewfest camp near Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12492] = { id = 12492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbrew's Dire Brew", description = "Coren Direbrew's corpse clutched this small cask tightly to its gut.  This must be his infamous Dire Brew!", progress = "Hey {name}, your face is all smudged!  Have you been to Blackrock Depths?", completion = "Ah, so Direbrew finally submitted his brew.  What a pity he had to die to do it...\n\nOh, well.  Bottoms up, eh?", objectives = "Give Direbrew's Dire Brew to Tapper Swindlekeg at the Brewfest camp near Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12493] = { id = 12493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "PvP Test", description = "Kill me some guys from the other side!  Those guys suck!  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.", objectives = "Kill 10 opponents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12494] = { id = 12494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Riding Trainer Advertisement (20)" }
quests[12495] = { id = 12495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience With The Dragon Queen", description = "Our assault against Angrathar has staggered the Scourge, but they remain unrelenting. From overhead they send their frost wyrms to strafe the field of battle, making an advance upon the gate itself impossible. The frost wyrm attacks must be stopped, but before we defile the bones of ancient dragons, we must gain permission from their queen.\n\nTravel southeast to Wyrmrest Temple and seek out Queen Alexstrasza. Tell her what we must do and ask her for guidance.\n\nGo now, {name}!", completion = "You have come seeking my council, mortal. This I know, but do you know what it is that you face?\n\n<Alexstrasza points northward.>\n\nNorth of here are the dying grounds of Galakrond - progenitor of dragonkind. It is from Galakrond that the Titans created the Aspects. Imagine, then, the power of Galakrond. His size alone was greater than all of the Aspects combined! Now attempt to understand what the Scourge do in the Great Dragonblight.\n\nFrost wyrms, mortal, should be the least of your concerns.", objectives = "Seek out Alexstrasza the Life-Binder at Wyrmrest Temple in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12496] = { id = 12496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience With The Dragon Queen", description = "Though I know you hunger to destroy the Scourge that stand before us at the Wrath Gate, we must first deal with the threat that looms overhead. Until the strafing assaults of the frost wyrms are halted, we cannot move forward.\n\nBut before we assault the dying grounds of dragons, we must first be granted permission. Venture now to the hallowed halls of dragonkind: Wyrmrest Temple. Once there, seek out Queen Alexstrasza.\n\nRide now, {name}! Southeast, to Wyrmrest!", completion = "You have come seeking my council, mortal. This I know, but do you know what it is that you face?\n\n<Alexstrasza points northward.>\n\nNorth of here are the dying grounds of Galakrond - progenitor of dragonkind. It is from Galakrond that the Titans created the Aspects. Imagine, then, the power of Galakrond. His size alone was greater than all of the Aspects combined! Now attempt to understand what the Scourge do in the Great Dragonblight.\n\nFrost wyrms, mortal, should be the least of your concerns.", objectives = "Seek out Alexstrasza the Life-Binder at Wyrmrest Temple in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12497] = { id = 12497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galakrond and the Scourge", description = "Atop the Wicked Coil, the Grand Necrolord of the Scourge, Antiok, sits upon the shoulders of the reconstructed storm giant lord, Thiassi. From there he commands the armies of undead to work day and night to unearth Galakrond's massive bones. Should they succeed in raising Galakrond, all of your efforts will have been for naught.\n\nWhile I cannot call down the full fury of the Red Dragonflight to assist you in your journey, I will grant you my blessing. Go now and speak with my majordomo, Torastrasza.", completion = "The bravery of mortals never fails to astound me. Death affixes its cold stare upon you and in return you rise to challenge its assertion! It is why your kind is so loved... and so hated.\n\nEven though the Red Dragonflight is entrenched in a war with Malygos, there is something that we can do to help.", objectives = "Speak with Torastrasza at Wyrmrest Temple in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12498] = { id = 12498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Ruby Wings", description = "Use this beacon to signal a Wyrmrest vanquisher. Climb upon its back and fly north to Galakrond's Rest. Once there, command the dragon to destroy the Scourge scavengers that work to unearth Galakrond. Once the area has been cleansed, fly to the Wicked Coil, overlooking Galakrond's Rest, to destroy Grand Necrolord Antiok and recover the scythe that he uses to control the wyrms.\n\nDo this and return to Queen Alexstrasza for a hero's reward!\n\n{name}, beware the rotting storm giants that wander the area!", progress = "Destroy the Scourge at Galakrond's Rest before it is too late!", completion = "I knew that you would return, {name}. You have served the Wyrmrest Accord and saved your people from certain death. Let it be known to all and let it be recorded for posterity!", objectives = "Destroy 30 Wastes Scavengers and recover the Scythe of Antiok. Return to Alexstrasza the Life-Binder at Wyrmrest Temple should you complete this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12499] = { id = 12499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Angrathar", description = "With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth.\n\nThe time to make your final stand is now, {name}. Return to Fordragon Hold and notify Highlord Fordragon.", completion = "Know this: all that you have done has led to this moment. Without your efforts, we would have been finished! Now, stand guard as I take to the field and end this!", objectives = "Speak with Highlord Bolvar Fordragon at Fordragon Hold and tell him of your victory over the Scourge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12500] = { id = 12500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Angrathar", description = "With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth.\n\nThe time to make your final stand is now, {name}. Return to the Kor'kron Vanguard and notify Saurfang the Younger.", completion = "My father was right about you, {name}. Everything that he said has come to pass - only one final duty remains unfulfilled. I will now lead the Kor'kron to the front line. The time to end this war is at hand. The Lich King's tyranny ends today!\n\nTake my post now, {name}, and stand guard over our forces.", objectives = "Speak with Saurfang the Younger at the Kor'kron Vanguard and tell him of your victory over the Scourge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12501] = { id = 12501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol", description = "Unsheathe that weapon, {race}. It's time to go on patrol!\n\nI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!", completion = "Well, {name}, at least you've made it back in one piece. I suppose that's worth something....", objectives = "Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'Valok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12502] = { id = 12502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: High Standards", description = "Listen, {class}. This is the Argent Crusade. Our men will fight to the end and never complain no matter what the conditions.\n\nThat said, we've taken some heavy casualties in this campaign and we've been hitting it hard with little or no sleep for months. That all takes a toll on morale, whether we admit it or not.\n\nIt may not seem like much, but seeing our standard raised over the battlefield is of considerable comfort to a soldier. Take these banners and raise them at the pedestals in Drak'Sotra.", completion = "Good work, friend.\n\nAmazing what a little of one's colors do for a battleground.\n\nYou'll want to head on over to Captain Rupert next. He's stationed at the wall, just northeast of here.", objectives = "Captain Brandon wants you to place the Argent Crusade Banner in the Drakkari Pedestals at Drak'Sotra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12503] = { id = 12503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Stand", description = "Despite our substantial successes in the lower third of Zul'Drak, we must still face the onslaught of the Scourge. Such is the way in this frigid hell.\n\nThe attacks are unrelenting, yet my men need rest. If you are willing, we could use your aid in reinforcing them.\n\nBelow in the courtyard you'll find no end to the fighting. Dispatch the Scourge there with all the zeal you can muster, {class}.", completion = "Your assistance in this matter is greatly appreciated. Were it not for your efforts, we would have difficulty in holding the unliving back from our steps.", objectives = "Commander Falstaav has tasked you with the destruction of any 10 Scourge in the courtyard at The Argent Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12504] = { id = 12504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Crusade, We Are Leaving!", description = "<The sergeant quickly reads through the orders you've handed him, a frown coming over his face.>\n\nLook, <lad/lass>, I'd love to just up and leave, but take a look out there. All of my people are fighting.\n\nTell you what, you've come this far, you think you're up to doing me a small favor? Head out there and round up my soldiers?\n\nTell 'em that the sergeant orders them to report back immediately. Lend them a hand if you will.", completion = "Alright then. We'll collect up the rest and head back to the stand.\n\nIt's a shame that we have to leave so soon. Doesn't quite feel like the job's done here, and quite frankly, I get the feeling that prophet in front of the altar is going to be big trouble!", objectives = "Sergeant Stackhammer at the Altar of Sseratus wants you to speak with 10 of his Argent Soldiers and tell them to report back to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12505] = { id = 12505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Orders for Sergeant Stackhammer", description = "{class}, you're here to help, right? I've got new orders for our forces that are currently deployed at the Drakkari altar to the north.\n\nYou can't miss it. Just head straight up the avenue. Sergeant Stackhammer shouldn't be hard to find.", progress = "What's this all about?", completion = "<The dwarf sergeant warily eyes the orders in your hand.>\n\nAre those new orders for me, mister?", objectives = "Commander Kunz has asked you to deliver the New Deployment Orders to Sergeant Stackhammer at the Altar of Sseratus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12506] = { id = 12506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Altar of Sseratus", description = "There's trouble at the altar of the snake god.\n\nThe presence of the Scourge has weakened the land, {race}. This in turn has weakened the wild gods.\n\nWe know that the Drakkari are taking advantage of this to do evil things to the gods.\n\nI need you to be my eyes and ears. The Altar of Sseratus is at the end of the avenue to the north. Sneak around the back and get a look inside of the main altar building.\n\nWhatever you do, avoid the prophet at all costs!", completion = "Dead?\n\n<The hexxer's spirit is visibly lowered at the news you bring.>\n\nThey've killed Sseratus and drunk deeply of his mojo; the prophet especially!\n\nWe must figure out a way to put an end to him before he drinks too much more!", objectives = "Hexxer Ubungo at The Argent Stand has asked you to investigate the main altar building at the Altar of Sseratus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12507] = { id = 12507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Mojo", description = "This bottle of strange mojo may be the key to what is truly going on here.\n\nThe Zandalari troll Hexxer Ubungo, back at The Argent Stand, may want to take a look at it.", progress = "What's that you have there?", completion = "That's the mojo of the wild gods, {class}!\n\nThis is not good!", objectives = "Deliver the Strange Mojo to Hexxer Ubungo at The Argent Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12508] = { id = 12508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mopping Up", description = "I couldn't help but overhear what you were talking to the sergeant about. That doesn't change the fact that we still have a job to do here.\n\nWhile you're out there, do you think you could help us to put some of those followers of Sseratus out of their misery?", completion = "Thanks, {class}. I'd have hated to leave without accomplishing what we came out here for in the first place.", objectives = "Corporal Maga at the Altar of Sseratus wants you to kill any combination of 10 Champions of Sseratus, Priests of Sseratus, or Drakkari Snake Handlers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12509] = { id = 12509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Intestinal Fortitude", description = "Finally, the patrol arrives!\n\nHere's the situation, {race}. We've lost many of our finest soldiers in this campaign and have had to call upon our recruits to fill in the gaps.\n\nWe've just fought one of our fiercest battles and many of the recruits were simply not prepared to face this enemy. There are more fights ahead, and I need them ready to follow orders.\n\nIf there's one thing I can't stomach, it's cowardice. Perhaps you can help them find the courage to continue.", completion = "Well done, {class}. And not a moment too soon. I've received word that a counter-attack is imminent.\n\nYou should be on your way. The next post is to the northeast, near the coliseum. Captain Grondel should be waiting for you there.", objectives = "Captain Rupert in Drak'Sotra wants you to restore courage to the cowering Crusade Recruits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12510] = { id = 12510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Elemental Fluids", description = "<The hexxer examines the decanter of mojo.>\n\nI have an idea for how to deal with the prophet of Sseratus. But first, we're going to need some things.\n\nThe Drak'Sotra Fields are directly to the south. Because of the stresses on the land from the Scourge and the deaths of gods, the wall between worlds has weakened and the elementals are flooding in.\n\nWe need the precious fluids of their lords. If you combine three links from the elementals a tether will be made, and one of their lords can be summoned.", progress = "Do you have the precious fluids?", completion = "Excellent. When combined with the mojo, these fluids will dilute the effectiveness of the mojo without completely eliminating it.\n\nNow, one more thing.", objectives = "Hexxer Ubungo at The Argent Stand wants you to acquire 3 Precious Elemental Fluids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12511] = { id = 12511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hills Have Us", description = "While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills. All in hopes of finding an alternate route into Icecrown.\n\nLieutenant Dumont, stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?", completion = "You were almost shot down, eh? Savage monsters - those Horde.\n\nPayback will come for what they've done. You can count on at least that much, {class}.\n\nNow, it's time to put you to work.", objectives = "Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12512] = { id = 12512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No One Behind", description = "Ahh, good. They sent someone.\n\nListen, {race}. We need a hand here. Our forces were pushed back and we've lost Drak'Sotra to the Scourge. Where they came from is anyone's guess....\n\nThe point is, we need every man we can get here, and some of our best have yet to return from battle.\n\nI need you to enter the ruins now that the fighting has died down and find our wounded, patch them up, and bring them here to me.\n\nScour Drak'Sotra! They couldn't have gone far.", progress = "Have you rescued our veterans, {name}?", completion = "Saved them all, did you? Outstanding!\n\nMaybe you'd consider sticking around the post here? We could sure use someone like you....", objectives = "Dr. Rogers at Drak'Sotra wants you to find Crusader Lamoof, Crusader Jonathan, and Crusader Josephine. Use the Crusader's Bandage on them, and escort them safely back to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12513] = { id = 12513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nice Hat...", description = "My hat? Yes, it's an unusual style, I know, from far away... few tailors here know how to make them.\n\nWhen I was young and hot-blooded, I wore it as a standing challenge. Many came seeking to defeat me and win it for themselves... but no one ever did.\n\nAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no longer duel.", progress = "I was unbeatable, in those days... proud, and rightly so. No challenger ever won this fine hat...", completion = "My... my hat! So... it WAS you. I'd thought so. The old scars ached when you drew near, but... so young! You've not changed at all!\n\nWell... so now you know my secret. I WAS beaten... once. Here: take this hat, in return for mine. You've more than earned it.", objectives = "Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos' Hat to him in Tanaris as proof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12514] = { id = 12514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushroom Mixer", description = "Now what we need is something to spike the mojo with. Something that'll make it so that when the prophet drinks it, he'll become less powerful.\n\nDrak'Agal lies to the east. There's a mushroom there that the natives call muddlecap fungus. I think it's exactly what we need.\n\nBring back lots of them. When we mix them into the mojo, the mind of anyone who drinks it will become muddled.", progress = "Do you have all of the fungus?\n\nOh, and watch out for the basilisks lurking over there.", completion = "<The hexxer nods his approval.>\n\nHand that fungus over and I'll mix it up with the mojo and elemental lord fluids.", objectives = "Collect 10 Muddlecap Fungus and deliver them to Hexxer Ubungo at The Argent Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12515] = { id = 12515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nice Hat...", description = "My hat? Yes, it's an unusual style, I know, from far away... few tailors here know how to make them.\n\nWhen I was young and hot-blooded, I wore it as a standing challenge. Many came seeking to defeat me and win it for themselves... but no one ever did.\n\nAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no longer duel.", progress = "I was unbeatable, in those days... proud, and rightly so. No challenger ever won this fine hat...", completion = "My... my hat! But... how did you...?\n\nWell... no matter. So, now you know my secret. I WAS beaten... once. Here: take this hat, in return for mine. You've earned it.", objectives = "Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos' Hat to him in Tanaris as proof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12516] = { id = 12516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Much of a Good Thing", description = "There. I've modified the mojo. Now when the prophet drinks it, not only will he lose some of his power, his mind will also be addled by the effects of the fungus.\n\nAt least that's the theory.\n\nAs for how to get him to drink it, might I suggest you simply throw it at him? No doubt he'll catch and drink it given the arrogance that he's displayed at the altar.\n\nUnless you can kill him, {class}, your Argent Crusade is about to come to a terrible end.", completion = "Amazing! You've saved your people and the rest of Northrend from his madness.\n\nUnfortunately there's more of this insanity occurring up in the higher tiers of Zul'Drak.", objectives = "Slay the Muddled Prophet of Sseratus and then return to Hexxer Ubungo at The Argent Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12517] = { id = 12517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rogues Deck", description = "Now that you have gathered all of the Rogue cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone or something.", progress = "I see that you have managed to collect a deck of Rogues!   I'm impressed.", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return.", objectives = "Use the Rogues Deck to summon a Darkmoon Fortune Teller and give the deck to them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12518] = { id = 12518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mages Deck", description = "Now that you have gathered all of the Mage cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone or something.", progress = "I see that you have managed to complete a deck of Mages!   Congratulations!", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return.", objectives = "Use the Mages Deck to summon a Darkmoon Fortune Teller and give the deck to them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12519] = { id = 12519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Whatdya Want, a Medal?", description = "Look at me, {race}. Do I look like I have time fer fillin' out reports?\n\nIt be all I can do to keep this post free o' the bloody Scourge, and they want me to mess with paperwork!\n\n<sigh> No sense in complainin'. I need to get the commander some kinda kill count from the last skirmish.\n\nYou wanna be helpful? Go and get me all the medals you can find from the dead trolls around here. That'll hafta be close enough.", progress = "You get those medals for me, {race}?", completion = "Well, now!\n\nYa saved me a fair bit o' work there lad. I'm grateful. I'll be sure ta make mention of ya in me report.\n\nOff with yeh now. Finklestein'll likely be waitin fer ya a bit west o' here.", objectives = "Captain Grondel outside the Coliseum wants you to gather 7 Drakkari Medallions from the nearby Drakkari Corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12520] = { id = 12520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhino Mastery: The Test", description = "No rough landing is going to stop ol' Hemet from mastering the largest game Sholazar has to offer. In the wilds northwest of the camp, the jungles are ruled by the mighty shardhorn rhino. You can prove your worth to the expedition, <lad/lass>, by showing me that you're tough enough to face down those powerful beasts.", completion = "Well, well, well, it looks like you've survived the rhinos, after all, and in pretty good shape if I do say so myself. But there's more to rhino hunting than just staring down the beast as it charges you and hoping your aim is true. No, you'll need more than that to take on the rhino patriarch that's rumored to dwell in the jungle.", objectives = "Kill 15 Shardhorn Rhinos and return to Hemet Nesingwary at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12521] = { id = 12521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where in the World is Hemet Nesingwary?", description = "When I heard that the legendary Hemet Nesingwary was setting sail for the Sholazar Basin, I offered to help fund his expedition. We know little of Sholazar,  but it's said to be a lush paradise in the midst of this frozen continent.\n\nHemet has agreed to send back samples of exotic plants, reagents, and crystals. There hasn't been any word from him. Monte Muzzleshot was supposed to be bringing them supplies, but he hasn't returned, either. If you'll look into it, I'll send you in my flying machine.", completion = "Aye, Hemet's here. He's at the camp, just go northwest toward the river and you'll soon see it. And for the love of the Light, lad, have him send someone to cut me down!", objectives = "Talk to Archmage Pentarus when you're ready to leave for Sholazar Basin. When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12522] = { id = 12522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need an Engine, Take an Engine", description = "She's ruined... ruined! I told that captain to be careful with such a precious cargo, but would she listen to me? No!\n\nWhen the ship ran aground, it damaged my flying machine, the Spirit of Gnomeregan. Now, we're left without any means to send our reports!\n\nThere is a chance, though, that the Venture Company's antics may work in our favor. They shot down another flying machine right about where Monte parachuted into the swamp to the east. Go there and retrieve the engine. It may be our only hope.", progress = "Well, were you able to get the engine? I just know that archmage who funded the expedition is getting nervous.", completion = "There... just set it down there. Be careful! If you ruin this one, we're in big trouble. Now, let's see what I can do.", objectives = "Weslex Quickwrench at the Nesingwary Base Camp wants you to bring him a Flying Machine Engine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12523] = { id = 12523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Have a Part, Give a Part", description = "Great, now that we've got an engine, we're going to need an assortment of other parts to get her back in flying condition. Don't worry, I know what I'm doing.\n\nA good mechanic can hold his creations together with anything, but we're better off if it doesn't come to that.\n\nAnyway, those Venture Company dullards have plenty of spare parts for their mining equipment all over Swindlegrin's Dig on the far side of that yellow crystal pillar to the northeast. Scoop up a few and bring them back here.", progress = "Did you get those parts?", completion = "With a little work, these should suffice. My poor flying machine might end up looking more like a Venture Company shredder, though. Poor girl will have to wait until we get back to Dalaran to be restored to her rightful form.", objectives = "Bring 7 Venture Co. Spare Parts to Weslex Quickwrench at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12524] = { id = 12524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Co. Misadventure", description = "Ever since we arrived, the Venture Company has hampered our efforts to secure our campsite and survey the area. Normally, we wouldn't care what they were up to, but they've started antagonizing our scouts and shooting down supply flights.\n\nWe can't allow this insult to stand. Hemet Nesingwary's expedition came here to hunt, and hunt it shall.\n\nGo to Swindlegrin's Dig, on the far side of the crystal pillar to the northeast, and kill any Venture Company employee you see!", completion = "That should hamper their operations, but I worry that the foreman will try to bring in more workers. We have to complete the job while we can.", objectives = "Debaar at the Nesingwary Base Camp wants you to kill 15 Venture Company members. You may kill either Venture Co. Ruffians or Venture Co. Excavators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12525] = { id = 12525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wipe That Grin Off His Face", description = "We must send Foreman Swindlegrin packing if we're going to shut down his mine permanently, but be careful. His bodyguard, Meatpie, is a large, mean ogre, and  isn't likely to let you see the foreman without a fight.\n\nThe two probably occupy a platform that would let them look out over the entire Venture Company operation at Swindlegrin's Dig.\n\nRemember, the dig is on the far side of the Suntouched Pillar to the northeast. Good luck, {name}.", completion = "What a relief to hear that the Venture Company will trouble us no more. You have my thanks, and that of Hemet for dealing with this problem. A game hunter cannot, in good conscience, lift her weapon against another person.", objectives = "Kill Foreman Swindlegrin and Meatpie and return to Debaar at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12526] = { id = 12526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhino Mastery: The Chase", description = "Well, that's settled then. We'll seek out this native sage and have a word with him. He's not likely to volunteer his services, though.\n\nI'm told he keeps a small lean-to near the Bones of Nozronn, just across the river to the south. Seek him out, introduce yourself, and ask what he requires to help us track down this patriarch of the rhinos.", completion = "What brings you to Rahm's shrine?", objectives = "Speak to Oracle Soo-rahm at the Bones of Nozronn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12527] = { id = 12527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluttonous Lurkers", description = "My master, Finklestein, is in the shrine at Heb'Valok to the northwest preparing a truth serum, and he needs basilisk crystals. Heb'Valok is on the west side of the road leading north before the Altar of Sseratus.\n\nThere are basilisks to the east at Drak'Agal.\n\nIf you grab the Zul'Drak rats and throw them at the basilisk, they will become gorged and docile after eating five. Then you'll be able to take their crystals.\n\nKilling the basilisk won't do you any good. That'd just break its crystals!", progress = "What's all this?\n\nBy any chance have you seen my no-good apprentice, Pestlepot?\n\nI sent him on an errand quite some time ago and he has yet to return!", completion = "Oh, most excellent! Thank you. The crystals appear to be in fine condition!\n\nI have no doubt that Pestlepot put you up to doing his chores for him. Nevertheless, your assistance in this matter is greatly appreciated!", objectives = "Deliver 5 Basilisk Crystals to Alchemist Finklestein in the shrine at Heb'Valok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12528] = { id = 12528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing Along", description = "My kill! You take my kill!\n\n<Gekgek taunts you with his spear.>\n\nYou dumb, {race}. Now you owe Gekgek! You be Frenzyheart slave. You slay many more beasts for Frenzyheart.\n\nYou go Frenzyheart Hill to northeast - you tell High-Shaman Rakjak you the new slave.\n\nGo, {race}! Go or I taunt you a second time!\n\n<Gekgek waves his spear around menacingly.>", completion = "You the new slave?\n\nGood. We running out.", objectives = "Report to High-Shaman Rakjak at Frenzyheart Hill as the new \"slave.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12529] = { id = 12529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ape Hunter's Slave", description = "You think you so great hunter, eh? You no Frenzyheart, you not know of hunt.\n\nGoregek is great ape hunter. He slay so many ape you can't count on claws.\n\nYou go with Goregek and hunt hardknuckles to east. You the slave, {race}. You do what Goregek tell you.", completion = "Goregek show silly {race} slave how it done.", objectives = "Kill 8 Hardknuckle Foragers and 6 Hardknuckle Chargers for High-Shaman Rakjak at Frenzyheart Hill.\n\nIf you lose Goregek's Shackles, speak to Elder Harkek in Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12530] = { id = 12530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tormenting the Softknuckles", description = "Slave thing!\n\nRakjak want me to babysit you while I kill hardknuckles. I feeling generous today, so I let you kill some too, but don't get in Goregek's way!\n\nRakjak not know yet, but Goregek has eye on big bad hardknuckle mama. We go to Hardknuckle Clearing to east and poke softknuckles with poker and she sure to come yelling!\n\n<Goregek rubs his hands together gleefully.>", completion = "Goregek take you to kill big mom of hardknuckles, eh? You lucky!\n\nDumb softknuckles squeal good!\n\n<Rakjak squeals loudly and breaks out laughing.>", objectives = "Goregek has given you a Softknuckle Poker for use on Softknuckles to draw the Hardknuckle Matriarch out of hiding. Slay the Hardknuckle Matriarch and report her death to High-Shaman Rajak at Frenzyheart Hill.\n\nIf you lose Goregek's Shackles, speak to Elder Harkek in Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12531] = { id = 12531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Underground Menace", description = "Lion killer, chicken chaser, new Frenzyheart slave...\n\nI know you no want to stay slave, so I tell you what to do. Show you better than the other Frenzyheart hunters and then Rakjak respect you.\n\nUnder sands of south river there a beast that kills wasp, apes, and even wolvar. He called Serfex. You bring claw of Serfex to Rakjak and maybe he release you from slaveness.\n\nHope Dajik teaching you good so Serfex be easy stuff.", progress = "I not ask for you, {race}. What you want?", completion = "You kill Serfex? I bet you follow mighty wolvar that kill Serfex and take claw.\n\nMy claw now.", objectives = "Locate Serfex under the sands of the southern river, slay him, and bring his claw to High-Shaman Rakjak at Frenzyheart Hill.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12532] = { id = 12532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flown the Coop!", description = "Dumb Goregek stumble into chicken house and let all the chickens go!\n\nThey all around hill - go get chickens back!\n\n<Elder Harkek shoos you away.>", progress = "You catch chickens?", completion = "Good! I was worried about foodstuffs. I already pretty hungry.\n\nThank you, {race}.", objectives = "Capture 12 Chicken Escapees for Elder Harkek.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12533] = { id = 12533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wasp Hunter's Apprentice", description = "Rakjak not dumb. Maybe you good at killing things. Maybe Frenzyheart can make you into real hunter.\n\nDajik hunts giant wasp things better than all wolvar. Go with Dajik to Sapphire Hive to southeast or to river in south and learn the hunt.", completion = "We kill many many wasps.\n\nRakjak don't think they run out.", objectives = "Kill 6 Sapphire Hive Wasps and 9 Sapphire Hive Drones for High-Shaman Rakjak in Frenzyheart Hill.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12534] = { id = 12534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sapphire Queen", description = "Bristlepine can be dangerous, but most stay far away from wolvar. Wasps on other hand not fear the Frenzyheart... they even kill some of our hunters.\n\nI know Rakjak want wasp queen dead, but no wolvar want to go into her hive. You go kill wasp queen in Sapphire Hive to southeast and get stinger for Rakjak. Me bet Rakjak like that.", progress = "You smell like wasp things.", completion = "You killed queen wasp! You stronger than Rakjak thought.\n\nMaybe wasps go away now and stop attacking Frenzyheart hunters.", objectives = "Bring the Stinger of the Sapphire Queen to High-Shaman Rakjak at Frenzyheart Hill.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12535] = { id = 12535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mischief in the Making", description = "You good hunter, but Frenzyheart can make you stronger. Harkek think maybe you ready for something more important.\n\nBefore Rakjak send you on important mission, you need gather things for Rakjak. All along river to south are blue crystals. Rakjak need lots of blue crystals.\n\nYou go get crystals now.", progress = "Almost ready for long journey. Gekgek come back with crocolisk just moment ago.", completion = "Good {race}! Okay, all ready.", objectives = "High-Shaman Rakjak at Frenzyheart Hill wants 8 Skyreach Crystal Clusters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12536] = { id = 12536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Ride", description = "Zepik is best hunter of the Frenzyheart. Zepik hunts big-tongues... ugly things near swamps that try to steal all stuff they can find.\n\nZepik going on long trek to break big-tongue shrine and try to scare them away. We no want big-tongues in this land anymore.\n\nThere a crocolisk chained on northeast side of hill, next to tree - go with Zepik and do what Zepik tell you.", progress = "They tell Zepik you good hunter for not being Frenzyheart.", completion = "We here! Must work fast.\n\nWatch out for big-tongues.", objectives = "Ride the captive crocolisk to Mistwhisper Refuge and then speak to Zepik for further instructions.\n\nIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12537] = { id = 12537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Definitely Strikes Twice", description = "Okay, the crystal things...\n\nThe big-tongues use the crystals to power their rain shrines. Zepik not know quite how it works, but Zepik does know that if they use wrong crystals, the clouds and the rain go crazy!\n\nZepik tried to sneak in at one of their other rain shrines, but it not go so well. It sure to go much better with two!\n\nTake crystals, place at big stone pillar shrine thing, then smash them to release power. Zepik not sure what will happen, so might want to step back after.", progress = "Zepik think this go much better with partner. You strong for not Frenzyheart.", completion = "It work so good!\n\nYou see lightning smash that oracle guy? So good!\n\n<Zepik rubs his hands together and chuckles maniacally.>", objectives = "Zepik wants you to smash the Skyreach Crystal Clusters in front of the Mistwhisper weather shrine.\n\nIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12538] = { id = 12538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mist Isn't Listening", description = "Gorillas and wasps are boring! Big-tongues the only thing fun to hunt.\n\nWhile we mess up rain shrine, we kill lots of mist big-tongues. That sure to make them not want to come back to village thing.\n\n<Zepik nods to himself confidently.>", completion = "I stab those big-tongues good.\n\nYou did okay I guess.\n\nNo, I just kidding! You good hunter. I glad to hunt with you.", objectives = "Zepik wants you to kill 12 Mistwhisper Gorlocs.\n\nIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12539] = { id = 12539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoofing It", description = "Okay, we done! Time to go back. No crocolisk to ride this time though.\n\nIf we go east and stay near ridge, it should lead all the way back near hill.\n\nNeed to be careful not to go far below ridge though or we might go right into big-tongue tree village thing. Zepik not think they like us right now.", completion = "Blown up by lightning?\n\n<Rakjak breaks out laughing for a moment.>\n\nYou good hunter. Rakjak like you. Maybe one day you can be honorary Frenzyheart!\n\nOnly maybe though!", objectives = "Find your way back to Frenzyheart Hill and speak to High-Shaman Rakjak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12540] = { id = 12540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Following Orders", description = "Okay <guy/lady>, Rakjak have very important job. You go capture injured big-tongue that tracker spotted at river to north.\n\nNot bring hunter this time because they maybe want to just kill it. I want to hide it so that I can poke it and make it tell me things.\n\nGo you and bring me big-tongue prize thing.", completion = "No kill me please! We was just looking for fish. We not want to die.", objectives = "Locate an Injured Rainspeaker Oracle for High-Shaman Rakjak at Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12541] = { id = 12541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, {race}. And remember, timing is everything!", progress = "You see, {name}, there is far more to true alchemy than mixing a few ingredients....", completion = "You've done it!\n\nThe intelligence gathered from that troll will undoubtedly be of great value. I'll be certain to make mention of your efforts in my report to the commander.\n\nThank you, {name}.", objectives = "Alchemist Finklestein at Heb'Valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12542] = { id = 12542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call Of The Crusade", description = "{class}! The Argent Crusade is looking for able bodied soldiers that are willing to set aside their differences and join forces to battle the forces of the Lich King. Will you take up our cause?\n\nShould you be interested, venture north to Light's Trust and speak with Crusader Valus.\n\nYou will find Light's Trust amidst the ruins of the sacked troll city of Jintha'kalar - bordering Zul'Drak.\n\nFarewell.", completion = "Mere footsteps from here lies the Drakkari empire.\n\n<Valus points east.>\n\nFor thousands of years the Drakkari remained isolated, preferring to keep within the boundaries of their sprawling temple cities and ziggurats. It was surprising then, to come upon this wreckage. Further up, beyond the foreboding stairs leading into Zul'Drak, Drak'Tharon Keep lies in ruin. The entire first tier of Zul'Drak, destroyed...\n\nWhy has the Scourge waited until now to attack?", objectives = "Report to Crusader Valus at Light's Trust in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12543] = { id = 12543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Offering for Soo-rahm", description = "We not know you, stranger, but we know you want something.\n\nWe will talk to Bones of Nozronn for you, but you must bring us offerings. We need powerful emperor cobra fangs to complete our oracle's necklace.\n\nGo to the Wildgrowth Mangal, northeast of our hut, find cobras and bring back best fangs. Then we make bones speak to you.", progress = "We must know -- do you bring fangs?", completion = "<The oracle inspects the fangs.>\n\nWe approve! Bones of Nozronn will speak to {name}!", objectives = "Bring 5 Intact Cobra Fangs to Oracle Soo-rahm, near the Bones of Nozronn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12544] = { id = 12544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bones of Nozronn", description = "Bones of Nozronn, Oracle Soo-rahm sends {name} to you!\n\nWe have prepared incense for you. Light it and place it near Nozronn's head and you will hear his voice.\n\n<Confused, you tell Soo-rahm that you haven't even told him your question.>\n\nTrue, we not know, but mighty Nozronn does. Do not doubt. Nozronn will answer your heart's question.\n\nGo. Nozronn not wait long.", progress = "Well, have you consulted the native oracle?", completion = "<Hemet listens as you describe what you learned.>\n\nWay to go, lad. No dead rhino tells Hemet Nesingwary where and what he can hunt. We'll show that heap o' bones.", objectives = "Use Soo-rahm's Incense near the Bones of Nozronn, then return to Hemet Nesingwary at Nesingwary's Base Camp with the information you learned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12545] = { id = 12545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleansing Of Jintha'kalar", description = "We wrested this ancient Drakkari temple from a swarm of invading Scourge. Not more than one-hundred paces from where we stand is the ruined city of Jintha'kalar. Scourge necromancers run amok, turning the living Drakkari trolls that remain into servants of the Lich King.\n\nAll are now lost to the Light. All must be purged.\n\n<Valus looks upon you sternly.>\n\nAll.", completion = "As you can see, the Scourge war machine presses onward, yet the armies of the Horde and the Alliance remain divided, making for easy prey. It is for this reason that we must remain united.\n\n<Valus is lost in contemplation for a moment.>\n\nThe Argent Crusade has use for a man like you. Perhaps you would be interested in joining our cause? To battle and die at the side of the Ashbringer?", objectives = "Crusader Valus at Light's Trust in Dragonblight has asked you to slay 15 Jintha'kalar Scourge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12546] = { id = 12546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclamation", description = "It is time, {name}.  The Etymidian is one of the most destructive forces ever created by the titans and I am loathe to unleash him in my lands.\n\nThere is little choice, however.  Our enemies have forced my hand and the fury of the titans will cleanse all.", completion = "I am grateful for your help, {name}.  It is my duty to watch over these lands and all life that dwells on them.\n\nThanks to you, that life will continue to thrive while the forces of death wage in the bordering regions.\n\nYour actions will not be forgotten.", objectives = "Go to the Avalanche in Sholazar Basin and use the Omega Rune to deploy Etymidian. Use him to slay 200 Scourge Minions, Bythius the Flesh-Shaper, Urgreth of the Thousand Tombs and Hailscorn.\n\nSpeak to the Avatar of Freya in Sholazar Basin when you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12547] = { id = 12547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Activation Rune", description = "This colossal being appears to be inactive.  You notice an empty rune-shaped slot on its chest.\n\nPerhaps you might be able to find the missing rune inside the nearby overlook.", progress = "<The rune-shaped slot on The Etymidian's chest appears to glow with faint power.>", completion = "<You hear the rumbling sound of stone grinding as The Etymidian's limbs come to life.>\n\nI am needed somewhere?", objectives = "Obtain the Omega Rune inside the Shaper's Terrace and bring it to The Etymidian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12548] = { id = 12548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Etymidian", description = "It is time, {name}.  The Waygate has been activated for the first time in seven centuries.  Use it to travel to where our final hope lies.\n\nLet us put an end to those who would seek to bring the taint of undeath to this pristine land.  Let us unleash the Etymidian.", completion = "<As you read the engravings on this stone colossus, you realize that this is the weapon that Freya spoke of.  This is the Etymidian.>", objectives = "Go through the Waygate in the southern end of Sholazar Basin and look for the weapon known as the Etymidian on the other side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12549] = { id = 12549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadsaber Mastery: Becoming a Predator", description = "If you've hunted with Hemet before, you know that he's tested his skill against many large cats, but the dreadsabers here in Sholazar are different. They're able to bring down larger game than I've ever seen a cat hunt. To overcome and kill such a predator is the mark of a true hunter.\n\nIf you seek to prove you're up to the challenge, test yourself against the dreadsabers. They live in the wilderness surrounding the camp and south of the river.", completion = "Well, you've proven yourself a capable hunter, but how are you as a tracker?", objectives = "Kill 15 Dreadsabers and return to Buck Cantwell at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12550] = { id = 12550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadsaber Mastery: Stalking the Prey", description = "I have heard that the natives tell stories of a large dreadsaber they call Shango. I haven't seen any evidence of this Shango's existence, but my injuries have kept me from venturing outside the camp.\n\nIf you fancy yourself something of a tracker, you might be able to find out the truth about Shango. Debaar said she saw some large tracks on her last outing. Go north from the camp toward Bittertide Lake, and search its southern shore for the prints.", completion = "<Buck listens as you recount your findings.>\n\nI think you may have found the proof we need for this Shango. And I think I have an idea as to where we can find him.", objectives = "Buck Cantwell at the Nesingwary Base Camp wants you to identify 3 Shango Tracks from the Dreadsaber Tracks near Bittertide Lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12551] = { id = 12551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Mastery: The Trial", description = "I warn you, stranger -- do not make any comments about crashing the ship. I already get enough of it from the rest of the expedition.\n\nIf you're looking to try your hand at hunting, though, you should test your skills against the wily mangal crocolisks. They live all along the river to the south, and in the Wildgrowth Mangal to the east. Prove you can hold your own against them and we'll talk again, hunter.", completion = "Impressive, {class}. Are you certain you're not a member of the expedition?\n\nNo, I'm certain of it. There would've been a crash joke in there somewhere.", objectives = "Kill 15 Mangal Crocolisks and return to Debaar at the Nesingwary Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12552] = { id = 12552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Necromagi", description = "When the trolls brought down Kolramas, it crashed next to us to the southeast. Unfortunately the crash did not destroy all of the Scourge within.\n\nNow they're raising our men from the dead and using them against us!\n\nThis will not be allowed to continue. You will see to it that their necromagi are slaughtered! Do we understand each other?", completion = "It's not enough!\n\n<The sergeant's voice cracks as he mourns the corruption of his fallen comrades.>\n\nWe must do more to show respect for the memories of those men!", objectives = "Sergeant Moonshard at Drak'Sotra has asked you to destroy 8 Hath'ar Necromagi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12553] = { id = 12553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skimmer Spinnerets", description = "Why do I always get the tough tasks to tackle?\n\nThe Scourge at Kolramas have plague sprayers that are getting dangerously close. You don't want to know what's going to happen if they start heading this way!\n\nI've got an idea for how we might bring them down, but first we're going to need something... something from their own creatures.\n\nThe Hath'ar skimmers can spin a very strong web that we can put to good use. Bring back some of their spinnerets.", progress = "Those spinnerets have to be intact if I'm going to be able to put them together into a device that you can use.", completion = "Those'll do!\n\nNow we're going to need some raw parts so that I can put the launching device together for you.", objectives = "Specialist Cogwheel at Drak'Sotra has asked you to collect 5 Intact Skimmer Spinnerets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12554] = { id = 12554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malas the Corrupter", description = "{name}, head back down there!\n\nYou'll find the leader of Kolramas, Malas the Corrupter, gloating from atop the crashed necropolis.\n\nKill him and bring me his head!", progress = "I look forward to mounting his head on a pike. Let's see him come back from that!", completion = "You're the hero of the hour, {name}.\n\n\n\nYou deserve our deepest respect, and something more I think.", objectives = "Sergeant Moonshard at Drak'Sotra insists that you return with the Head of the Corrupter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12555] = { id = 12555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tangled Skein", description = "There! One tangled skein thrower ready and waiting for you to take those plague sprayers down.\n\nYou just aim and let loose. The webbing should foul up their hover spells long enough to cause them to crash to the ground just like Kolramas.\n\nKind of poetic. I like that!", completion = "Yay! You're the best, {name}!\n\nI wasn't looking forward to being sprayed with Scourge stuff, that's for sure! I guess it's going to be hard for those stupid nerubians to spread their evil now!\n\nHow about I give you a little something for saving my skin?", objectives = "Specialist Cogwheel at Drak'Sotra has asked you to use the Tangled Skein Thrower in order to cause the destruction of 5 Plague Sprayers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12556] = { id = 12556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhino Mastery: The Kill", description = "Now that we know where to find Farunn, all that remains is the battle against the great beast. Are you ready to take on this rhino, {name}? For all the spirit's blustering, I'm certain it was telling the truth about the beast's strength.\n\nWhen you're ready to face him, head north past the Suntouched Pillar and look for Farunn on the northeast shore of the Bittertide Lake. It may even venture near the Glimmering Pillar. Bring back its horn to commemorate your kill.", progress = "Did you kill the beast?", completion = "<Hemet examines the horn.>\n\nAn astounding trophy from an amazing animal! {name}, I've been hearing rumors of even bigger, more ferocious game in the northern reaches of the basin and I'd like you to help us track it down.", objectives = "Bring Farunn's Horn to Hemet Nesingwary at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12557] = { id = 12557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lab Work", description = "I assume by your interruption that you wish to be numbered among those I am considering for apprenticeship.\n\nA worthy aspiration...\n\nShould I someday choose to accept your petition, I must be confident that you can find your way around my laboratory. I have many ingredients here; some plentiful, and others in short supply.\n\nTake your time, {class}. Find a muddy mire maggot, a withered batwing, an amberseed, and some chilled serpent mucus.\n\nSucceed, and I'll know to take your request seriously.", progress = "Have you become accustomed to my laboratory, {class}?", completion = "Yes, yes, that's a good start.\n\nShould I call upon you to help me with an actual recipe, you'll need to locate ingredients in a timely manner.\n\nKeep that in mind, {class}.\n\nFarewell.", objectives = "Alchemist Finklestein at Heb'Valok wants you to find a Muddy Mire Maggot, a Withered Batwing, an Amberseed, and some Chilled Serpent Mucus from within his laboratory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12558] = { id = 12558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadsaber Mastery: Ready to Pounce", description = "Shango awaits, {name}. If you have succeeded in your tracking, he will not know that you stalk him, and you will need the advantage.\n\nHe is supposed to be bigger, stronger, and more ferocious than the other dreadsabers of the basin. Travel north, to the western shore of Bittertide Lake and near the falls that feed it, do battle with Shango. If you succeed, return with his pelt.", progress = "Have you taken on Shango?", completion = "What an exquisite pelt from such a noble animal! It heartens me to see that the rumors about Shango were indeed true, {name}. Your pursuit of the creature has been flawless. You are a true huntsman.", objectives = "Bring Shango's Pelt to Buck Cantwell at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12559] = { id = 12559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering the Waygate - The Makers' Perch", description = "It is time then.  Let us activate the waygate.\n\nYou will find the first switch inside the Makers' Perch in the western edge of the basin.\n\nBeware, {name}.  The titans used the perch to watch over their creations.  Many of their stone servants still guard the place.", progress = "You're back, little one.  I was beginning to worry about your well-being.", completion = "We're halfway there, {name}.  One more switch needs to be activated before we can retrieve the Etymidian.", objectives = "The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Makers' Perch and use the Activation Switch Gamma.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12560] = { id = 12560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Mastery: The Plan", description = "The mangal crocolisk is a master of the ambush, and I intend to beat the best at his game. To do that, we'll need to construct a convincing camouflage for you. We'll use plants that grow in the sandy soil of the riverbanks and lake beaches.\n\nThe sandfern is best for this purpose. It grows in the sandy areas near the shores of the Seabreach Flow, just to the south, Bittertide Lake and Bittertide Falls, to the north, and the edges of River's Heart, the large lake beyond the mangal to the east.", progress = "Did you bring all the ferns we'll need?", completion = "<Debaar accepts the sandfern fronds from you and starts bending them around your body.>\n\nYes, this should work. Stand still! We'll make a bush of you yet.", objectives = "Bring 5 Sandfern fronds to Debaar at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12561] = { id = 12561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Issue of Trust", description = "This should never have happened.  The forces of undeath storm the very cradle of life!\n\nIf you're not here to destroy the minions of the Lich King, then leave at once.  Do not incur my wrath by distracting me from my duties.", progress = "Do not waste my time, mortal.  The titans' creations must be defended!", completion = "Very well, {race}.  I am satisfied that you're not one of the Lich King's minions... perhaps there is something you can do for us after all.", objectives = "Obtain Freya's trust by destroying 6 Blighted Corpses and 10 Bonescythe Ravagers in the Lost Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12562] = { id = 12562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drakkari Do Not Need Water Elementals!", description = "Intelligence reports that ever since those water elementals appeared in the Drak'Sotra Fields, a number of Drakkari shaman have come down from the upper tiers of Zul'Drak to take control of them.\n\nI cannot stress enough, <sir/ma'am>, how dangerous that could prove. We do not want them to have water elementals at their disposal.\n\nThe commander has ordered that these Drakkari water binders are to be put to the sword. Head south when you're ready.", completion = "Excellent work, sir!\n\nI'll see to it that the commander is apprised of your mission results.", objectives = "Sub-Lieutenant Jax at The Argent Stand has asked you to kill 10 Drakkari Water Binders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12563] = { id = 12563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol", description = "Unsheathe that weapon, {race}. It's time to go on patrol!\n\nI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!", completion = "Well, {name}, at least you've made it back in one piece. I suppose that's worth something....", objectives = "Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'Valok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12564] = { id = 12564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Something for the Pain", description = "Gritty as my men are, they're still mortal.\n\nWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.\n\nThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.\n\nThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.", progress = "Have you collected the water-poppies, {name}?", completion = "Fine specimens, {name}.\n\nOn behalf of my soldiers, I thank you for your efforts today.\n\nCaptain Rupert is likely the next stop on your patrol. He's stationed at the wall just east of here.", objectives = "Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12565] = { id = 12565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of Zim'Abwa", description = "I am heartened to see the zeal with which your Argent Crusade is dealing with the Scourge, {race}. I would like to help with your efforts.\n\nThe Drakkari trolls of this once-great city used to make regular offerings to their gods, but now neglect them, or worse.\n\nIf you were to make offerings to the gods, they would show their appreciation in return.\n\nZim'Abwa's statue is just to the southwest. Zim'Abwa would gladly accept your offerings of Drakkari artifacts as a sign that you are protecting Zul'Drak.", progress = "<Zim'Abwa stares inscrutably to the north and the south.>", completion = "<If Zim'Abwa could move his face, Zim'Abwa would make a vicious grin.>", objectives = "Hexxer Ubungo at The Argent Stand wants you to present 10 Drakkari Offerings to the statue of Zim'Abwa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12566] = { id = 12566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help for Camp Winterhoof", description = "I am Longrunner Nanik of the Taunka, sent by the chieftain of Camp Winterhoof to seek out allies in the fight against the vrykul. They mass to the west and south of our village, and though we slay 10 of them for every one of our dead, we cannot hold.\n\nApothecary Scyllis has promised to send brave {class}s northwest to our aid. Will you help my people fend off the vrykul assaults?\n\nFollow the road far to the northwest, across the river, and into the foothills of the mountains to reach Camp Winterhoof.", completion = "So, Nanik did find help then? Tell me, {name}, how is it you made it here without him? None know this land better than the Taunka.", objectives = "Speak with Chieftain Ashtotem at Camp Winterhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12567] = { id = 12567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Zim'Abwa", progress = "<Zim'Abwa's stony visage pierces your soul.\n\nZim'Abwa is pleased, but wants you to show more appreciation and respect by giving him more Drakkari offerings.\n\nHe will reward you in kind.>", completion = "<You sense Zim'Abwa's approval. Somehow you know that Zim'Abwa wants more tribute!>" }
quests[12568] = { id = 12568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Done to Death", description = "Trust me, {race}. I know....\n\nThe smell of burnt flesh has become sickening to even me, a Forsaken. Nevertheless, it is our solemn duty to ensure that our brethren never walk with the Scourge.\n\nPour this oil on the corpses of our fallen to ensure that we never face them on the battlefield as enemies.", completion = "Thank you, {name}.\n\nIt's not the most glorious job on the battlefield, but it must be done. I'll make note of your service in my report.\n\nCaptain Grondel is likely waiting for you to the northeast, just outside the amphitheater.", objectives = "Captain Rupert wants you to use the Incinerating Oil on 5 Defeated Argent Footmen in Drak'Sotra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12569] = { id = 12569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Mastery: The Ambush", description = "The largest crocolisk in the basin, known around here as \"Bushwhacker\" for his ambush prowess, likes to sun himself in the shallow waters of River's Heart. It's the large lake at the basin's center, and is to the east of our camp.\n\nI want you to take the camouflage I've prepared and hide on the western beach of River's Heart and ambush Bushwhacker when he shows himself. Bring back his mighty jaws if you are able to overcome him.", progress = "Did our plan work?", completion = "<Debaar listens as you describe the failure of the disguise.>\n\nWhat do you mean, our plan didn't work as intended?\n\nWell, you did manage to get the kill, to your credit. Look at the size of this jaw! Hemet will be proud of our efforts. This crocolisk was truly a monster.", objectives = "Bring Bushwhacker's Jaw to Debaar at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12570] = { id = 12570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortunate Misunderstandings", description = "I sorry! I not mean to get you in trouble!\n\n<The injured oracle stares at you blankly for a long while.>\n\nYou save me! We thank you. We going to go back to village now. You come too... you can stay with us! Puppy-men kind of mean anyway.\n\nLet me know when you ready to go, okay?", progress = "Who you? You stink of puppy-men.", completion = "You help us? You welcome then, dryskin.", objectives = "Escort the Injured Rainspeaker Oracle to Rainspeaker Canopy and speak to High-Oracle Soo-say.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12571] = { id = 12571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make the Bad Snake Go Away", description = "We were here long before the puppy-men came. This is very sacred place - we will not leave.\n\nYou seem like maybe you good, but we have Lafoo stay with you just in case. You understand we think.\n\nThere snakes thing that keeps trying to eat our hatchlings. Go with Lafoo and make them stop, okay? Especially big one near waterfall to northeast.", completion = "Snake gone?\n\nGood {race}. We thank you.", objectives = "High-Oracle Soo-say in Rainspeaker Canopy wants you to kill Venomtip and 10 Emperor Cobras.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12572] = { id = 12572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gods like Shiny Things", description = "Soo-say said we go with you. You be nice, okay?\n\nOoh, ooh! We know! We can make Soo-say happy if we bring back more offerings for shrine! We not need to go far, there's always stuffs to dig up around village... just look for sparkles in dirt!\n\nLet's go! Let's go! More offerings for shrine!", progress = "Hello dryskin. You get along with Lafoo good?", completion = "Shinies for the Great Rain Stone! Good! Good!\n\nWe offer these right away. Lafoo thought of this, yes? He a very smart Rainspeaker.", objectives = "Collect 6 of the treasures that Lafoo digs up and bring them to High-Oracle Soo-say in Rainspeaker Canopy.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12573] = { id = 12573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Peace", description = "We have great idea. You were friends with puppy-men, they maybe listen to you.\n\nWe want you to go give offering to Shaman Vekjik. He southwest where river turns into waterfall.  Tell puppy-man we no want fight. Tell him we play nice.\n\nYou good {race}. We trust you do this right.", progress = "Puppy-men play nice now?", completion = "So mean! We only be nice and they only be mean.\n\nThey keep messing with great stones... maybe they not know great stones are sacred.", objectives = "High-Oracle Soo-say at Rainspeaker Canopy wants you to give a peace offering to Shaman Vekjik and then return with his response.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12574] = { id = 12574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back So Soon?", description = "<High-Oracle Soo-say stares at your forehead for a while before speaking.>\n\nSoo-gan ask for help. We think they might have been attacked by puppy-men again.\n\nWe sending you and Jaloot to help... follow west river up to Mistwhisper Refuge. Do what Soo-gan says... hit the puppy-men on the nose if they being mean, they don't like that.\n\n<High-Oracle Soo-say goes back to staring at your forehead as you leave.>", completion = "We think we seen you before. You visit Mistwhisper village sometime already?\n\nSoo-say said you good. Soo-say smart, so we trust you too.\n\n<Mistcaller Soo-gan offers an awkwardly large smile.>", objectives = "Travel to Mistwhisper Refuge and speak to Mistcaller Soo-gan.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12575] = { id = 12575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Mistwhisper Treasure", description = "So some puppy-men come and smash blue crystals at Great Mist Stone! Lots of rain and lightning and badness... blue is wrong crystal for Great Mist Stone! Dumb puppy-men.\n\nAfter lightning, puppy-men stole big treasure we found in the sea-lake. We need treasure back to give to Great Mist Stone! Mist Stone is angry after what the puppy-men did!\n\nOne who took it named Tarter... no, Tiktak... no, no... Tartek. That it, Tartek! He went to the camp thing to north. Go get treasure back!", progress = "Dumb puppy-thieves.", completion = "You did it! You strong and nice! Good friend of Mistwhispers!\n\n<Mistcaller Soo-gan lets loose a big toothy grin.>", objectives = "Kill Warlord Tartek and retrieve the Mistwhisper Treasure for Mistcaller Soo-gan at Mistwhisper Refuge.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12576] = { id = 12576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forced Hand", description = "We try to be nice to puppy-men ever since they came, but they nothing but mean.\n\nWe okay with them being dumb - they not do much harm. Now they mess with sacred shrines though. Sacred shrines not for messing with. The Great Stones are here from all the way back when the Great Ones made us.\n\nWe wouldn't know what to do if the Great Mist Stone were hurt. Go to their camp to north... make puppy-men stop and not come back!", completion = "You squash good. Thank you for help.", objectives = "Kill 8 Frenzyheart Spearbearers and 6 Frenzyheart Scavengers for Mistcaller Soo-gan at Mistwhisper Refuge.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12577] = { id = 12577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Time!", description = "You're a good dryskin. Mistwhisper safe, treasure safe, and puppy-men sure to leave us alone now.\n\nYou go back to Rainspeaker Canopy and tell Soo-say you done good.", completion = "You back so soon!\n\nWent good then, yeah?", objectives = "Return to Rainspeaker Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12578] = { id = 12578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Angry Gorloc", description = "I not think you be back in time to go out again, but I wrong. I sending Moodle to nearby Mosswalker friends to bop silly Mosswalkers for not coming see shrine. Their village is east, up ridge, northeast of broken pillar.\n\nYou go with Moodle! He extra smart Rainspeaker... you listen to him good-like.", progress = "Soo-say fumbles a bit, but he's not dumb. I do think he's been far too forgiving though... the puppy-men are not going to stop or leave us alone. The only way to stop them is to kill them... there is no \"peace.\"\n\n<Moodle puffs up his chest and points to himself.>\n\nThat I am good at.", completion = "Before you say anything, do not assume me as foolish as most of the Oracles you've met. I've been into the world a bit, I've learned your language, and I'm not easily duped.\n\nI knew the Mosswalkers were dead before we ever came, though I didn't know that the undead were behind it.\n\nThey are not supposed to be able to enter this land... the destruction of the Lifeblood Pillar must have allowed them in somehow. We must see to it that they leave.", objectives = "Travel to Mosswalker Village and speak to Moodle once you've arrived.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12579] = { id = 12579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifeblood of the Mosswalker Shrine", description = "I've always suspected that the pillars have been the main reason for our weather and seclusion from the undead... this confirms it a bit.\n\nNot terribly long ago, there was a sound of a great explosion when the Lifeblood Pillar fell. The weather changed for the mosswalkers almost immediately... it began to snow, something we never see.\n\nThey were able to stop the snow by bringing more lifeblood crystals to the Great Moss Stone. Perhaps if we can do the same, it will help ward off the undead as well.", progress = "The Mosswalkers were good people... they did not deserve this.", completion = "We might be too late for the shards to make a difference, but our options are somewhat limited.", objectives = "Moodle wants you to collect 10 Lifeblood Shards, but stay away from the cave inside of the pillar itself.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12580] = { id = 12580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosswalker Savior", description = "There's some small chance that the Mosswalkers are not all dead yet... and at the very least, they deserve to not be butchered like this.\n\nLet's find some revenge for this slaughter and see if there are any to be saved in the process.", progress = "I wish I had known how key the pillars and the stones were much earlier... perhaps I could have prevented this.", completion = "I'm very glad there were some to be saved... with luck, they'll make it back to Rainspeaker Canopy safely.", objectives = "Moodle wants you to rescue 6 of the Mosswalker Victims in Mosswalker Village, though some of them may no longer be alive to save.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12581] = { id = 12581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Burden", description = "Perhaps the crystals will ward off the undead gradually, but there is one more thing that must be done.\n\nWe need to find the leader of these undead and kill him to ensure there's no one to push the wretches back upon us. If my suspicions are correct, he will be somewhere inside the fallen pillar... the Sundered Shard.\n\nThe corpses being dragged there would suggest as much anyway.\n\nI'll place the shards and bring the news to Soo-say... I'll leave the rest up to you.", progress = "<The phylactery rests ominously on the ground next to Artruis' dead form.>", completion = "<Inside Artruis's Phylactery you see what seems like an endless void... and you think you hear screaming in the distance from somewhere inside.>\n\n<As you're about to leave, you see an object floating in the void, just barely in reach.>", objectives = "Kill Artruis the Heartless.\n\nMoodle will not be able to accompany you on this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12582] = { id = 12582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzyheart Champion", objectives = "I know you weren't traitor thing like others said. We hunt together... I know you better than all of them. Thank you for saving me.\n\nMay sound funny... I not a big fan of big-tongues... but even I feel little bad for big-tongue dying like that though...they fight good enough they deserve fair fight.\n\nYou want to be friends with Frenzyheart again? I think I can convince them that you save me and got the big-tongues good. I no want you to make me look dumb though, so you sure no more big-tongues for you?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12583] = { id = 12583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crashed Sprayer", description = "I know that one of those plague sprayers crashed somewhere within Drak'Sotra to the west of us.\n\nWhy don't you see if you can find it. I can use the parts from the sprayer to create the device that's going to bring those things down!", progress = "Do you have the parts? Huh? Do you?", completion = "<The specialist steps back a bit when presented with the parts.>\n\nEw, those things are totally gross!\n\nOkay, okay, hand them over and I'll see what I can do. I probably should have had you take them to a priest first for purification.", objectives = "Specialist Cogwheel at Drak'Sotra has asked you to collect Plague Sprayer Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12584] = { id = 12584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pure Evil", description = "We know that Kolramas, the crashed necropolis to the southeast, was carrying a large amount of an ore known as saronite when the trolls shot it down.\n\nMy scouts tell me that much of the saronite is strewn about within the innards of that thing.\n\nEitrigg and his friends back at The Argent Stand want a bunch of the stuff so that they can study it.\n\nI want you to head in there and see if you can collect enough for them.", progress = "Yes, {class}?\n\nPlease tell me that you have the saronite that we requested Captain Rupert to acquire?", completion = "Can you not feel the pure evil of the stuff?\n\nWe must use the expertise and magics at our disposal, combined with the power of the Holy Light, to pierce the veil of iniquity surrounding this tainted ore. We must determine its origins.\n\nQuickly, hand the saronite to me!", objectives = "Captain Rupert has asked you to collect 10 Chunks of Saronite and deliver them to Eitrigg at The Argent Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12585] = { id = 12585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Creature Comforts", description = "Well, it ain't glamorous, but it needs doin'.\n\nMy troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya.\n\nWhat they need is a nice fire to dry 'em out and lighten their spirits.\n\nThis part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture.\n\nRound us up some fuel for burnin' and we'll be mighty grateful.", progress = "Ya got the wood fer a fire, {race}?", completion = "Mighty kind of ya, {name}. Mighty kind indeed.\n\nNow you'll be findin' Cap'n Arnath due west o' here, just over the rise.", objectives = "Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12586] = { id = 12586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Bigger Game", description = "Well, {name}, you've been an enormous asset to the expedition so far. Debaar, Buck, and I couldn't have have assembled such an amazing collection of trophies without you.\n\nBut, I hear there are even fiercer monsters in other parts of the basin. I've sent a search party up north to get an idea of what other beasts await us.\n\nI'd like you to meet up with them and see what they've found. Head north, beyond Bittertide Lake and search for the encampment.", sourceObjective = "Talk to <x> at <x>.", sourceObjectiveStatus = "unverified-source-field" }
quests[12587] = { id = 12587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol", description = "Unsheathe that weapon, {race}. It's time to go on patrol!\n\nI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!", completion = "Well, {name}, at least you've made it back in one piece. I suppose that's worth something....", objectives = "Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'valok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12588] = { id = 12588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Can You Dig It?", description = "One of our troops came across an old treasure map during our last offensive. If what it shows is true, then there are priceless troll artifacts nearby.\n\nMy soldiers have their hands full, pressed between the Drakkari and the Scourge. I need you to follow up on this intelligence.\n\nTake this shovel and use it at the loose dirt mounds to the southwest. Return to me after a diligent search has been conducted.", completion = "Thank you for looking into this for me, {name}. I'll make mention of your service in my report.\n\nYou'll likely want to visit Captain Rupert next. He's stationed at the wall due east of here.", objectives = "Captain Brandon in Drak'Sotra wants you to use the Steel Spade on the nearby Ancient Dirt Mounds to recover the Ancient Drakkari Relic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12589] = { id = 12589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick, What Kick?", description = "So you think you can shoot?\n\nWell, let's give it a try. Here, we'll start you out with something nice and gentle. Don't worry, it's got no kick to it at all. Remember, don't point that gun at anything you don't intend to fire at.\n\nNow, when you're ready, just take aim at that apple on top o' old Lucky Wilhelm's head and let 'er fly!", progress = "Satisfied with the results?", completion = "You're not a bad shot, but you'll get better with practice. How would you like to make a little wager?", objectives = "Using the RJR Rifle, shoot the apple on top of Lucky Wilhelm's head, then speak with Drostan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12591] = { id = 12591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Throwing Down", description = "Clever...\n\nJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!\n\nNow we're caught between two nethurbian armies and our predicament is worsening by the minute.\n\nAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.\n\nTake these grenades and throw them down their craters to the northwest.", completion = "We're not out of the woods by any means, but your efforts have helped to slow the enemy down.\n\nCaptain Grondel up in Drak'Agal will likely have need of you.\n\nFarewell, {name}.", objectives = "Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nethurbian Craters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12592] = { id = 12592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Hunter's Challenge", description = "So y'have something of a hunter's instinct. You're not a bad shot, and Hemet hasn't driven you out, so he must be planning on including you in the hunt.\n\nHow'd you like to have a bit of a competition, just me and you?\n\nHemet and the others will ask you to help in their hunting. Along the way, you and I will count up the kills we contribute to their goals. Now, this isn't something you can win in the blink of an eye, and you'll find yourself killing many different kinds of creatures. Good luck!", completion = "So, you've come to concede already?\n\n<Drostan's jaw drops as you tell him you've already made all your kills.>\n\nNo way! How in Azeroth did you do that? I just made my 58th. So close!\n\nBut fair's fair. I underestimated you, {name}, but you've earned this victory fair and square.", objectives = "Kill 60 Game Animals while you aid Hemet and his companions in their hunting. When you've killed your 60, return to Drostan at the Nesingwary Base Camp to compare numbers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12593] = { id = 12593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service Of The Lich King", description = "All that I am: anger, cruelty, vengeance - I bestow upon you, my chosen knight. I have granted you immortality so that you may herald in a new, dark age for the Scourge.\n\nGaze now upon the lands below us. The Scarlet Crusade scurries to undo my work, while Light's Hope stands defiantly against us - a blemish upon these Plaguelands. They must all be shown the price of their defiance.\n\nYou will become my force of retribution. Where you tread, doom will follow. Go now and claim your destiny, death knight.", completion = "You have heard the call of the Lich King, {class}. Now is the time to answer your master.", objectives = "Report to Instructor Razuvious in the Heart of Acherus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12594] = { id = 12594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Couldn't Care Less", description = "Of all the posts, they throw me in this one.\n\nThe place is flooded with putrid, stagnant water and now it's host to sewage elementals!\n\nI don't really know what they are or why they're here, and frankly I couldn't care less. What I do know is they're making a mess of my sector! How am I supposed to conduct any dignified military operations with those foul things roaming around?\n\nGet out there, {class}, and don't come back 'til you've cleared your share of 'em off of my battlefield!", progress = "You clear the area of bog beasts yet, {class}?", completion = "You sure about that, {race}?\n\nSeems to me like there are more of them things out there now than when you started!", objectives = "Captain Grondel wants you to kill 7 Mossy Rampagers in Drak'Agal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12595] = { id = 12595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Bigger Game", description = "Well, {name}, you've certainly proven your mettle as a hunter of all kinds of game animals -- rhinos, cats, and crocolisks. For some members of the expedition, these creatures are sufficient to test their hunting skills, but others, like myself, crave larger challenges.\n\nDorian Drakestalker went north, across Bittertide Lake and established a camp there. He's heard rumors of gigantic primordial drakes. Just imagine what a quarry they would be! Go check up on Dorian and see if he's had any luck.", completion = "So old Hemet didn't forget about me, after all. I suppose he's going to want to participate in the hunt once we've done all the hard work. Don't worry, there are plenty of drakes to go around. Hemet will get his wish.", objectives = "Speak with Dorian Drakestalker at Dorian's Outpost in Sholazar Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12596] = { id = 12596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pa'Troll", description = "Welcome to The Argent Stand, scrub. I am Commander Kunz, but you - you can call me... Commander.\n\nDon't think you're going to just cruise through my region, picking which missions you're going to participate in, answering to no one.\n\nHere, you report to me and you follow my orders to the letter. Understood?!\n\nFirst, you're going to get familiar with my men and the region we're charged with clearing.\n\nReport to each of them and do as they ask. Return to me when your patrol is done.", completion = "It's about time you got your carcass back here! Thought we'd lost ya to the Scourge - not that it would've been a great loss....\n\nIf you're going to continue to serve the Crusade, you'd best make a more impressive showing.\n\nTake note, {race}! Your future patrols will be rewarded based on your timeliness.\n\nDismissed.", objectives = "Commander Kunz at The Argent Stand wants you to visit the four Argent Crusade posts, follow their leaders' orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Southeast of here.\n\nCaptain Grondel is posted in Drak'Agal, due east.\n\nAlchemist Finklestein is posted in Heb'Valok, to the north.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12597] = { id = 12597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something for the Pain", description = "Gritty as my men are, they're still mortal.\n\nWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.\n\nThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.\n\nThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.", progress = "Have you collected the water-poppies, {name}?", completion = "Fine specimens, {name}.\n\nOn behalf of my soldiers, I thank you for your efforts today.\n\nCaptain Rupert is likely the next stop on your patrol. He's stationed at the wall just east of here.", objectives = "Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12598] = { id = 12598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Throwing Down", description = "Clever...\n\nJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!\n\nNow we're caught between two Nerubian armies and our predicament is worsening by the minute.\n\nAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.\n\nTake these grenades and throw them down their craters to the northwest.", progress = "Have you sealed the nerubian tunnels, {name}?", completion = "We're not out of the woods by any means, but your efforts have helped to slow the enemy down.\n\nCaptain Grondel up in Drak'Agal will likely have need of you.\n\nFarewell, {name}.", objectives = "Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nerubian Craters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12599] = { id = 12599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Comforts", description = "Well, it ain't glamorous, but it needs doin'.\n\nMy troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya.\n\nWhat they need is a nice fire to dry 'em out and lighten their spirits.\n\nThis part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture.\n\nRound us up some fuel for burnin' and we'll be mighty grateful.", progress = "Ya got the wood fer a fire, {race}?", completion = "Mighty kind of ya, {name}. Mighty kind indeed.\n\nNow you'll be findin' ol' Finklestein due west o' here, just over the rise.", objectives = "Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12600] = { id = 12600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upper Deck Promo - Bear Mount" }
quests[12601] = { id = 12601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, {race}. And remember, timing is everything!", objectives = "Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12602] = { id = 12602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, {race}. And remember, timing is everything!", objectives = "Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12603] = { id = 12603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharpening Your Talons", description = "The primordial drakes occupy most of the area to the north and east, and I can feel the heat of their breath even at this distance. Before we can challenge the mightiest among the drakes, we must test our skills against the lesser creatures.\n\nStill, don't let your guard down; any one of these beasts can devour a man whole. Once you've familiarized yourself with the combat tactics of these drakes, return and I will tell you our next step.", completion = "I can hear the confidence in your words. Good, the experience will come in handy when we face the queen of the drakes.", objectives = "Kill 6 Primordial Drakes and then speak with Dorian Drakestalker at Dorian's Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12604] = { id = 12604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Congratulations!", objectives = "You made excellent time on that patrol. It appears that you may be of use to us after all.\n\nAs promised, here's a little something extra for your efforts.\n\nKeep up the good work, {name}.\n\nDismissed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12605] = { id = 12605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Bait", description = "We're not likely to get Broodmother Slivina's attention waving our arms around like fools, but if we're smart, we can bait her into fighting us. We'll also secure more, uh, fodder for my little project.\n\n<Dorian glances over at Zootfizzle.>\n\nBut don't worry about that for now. Just look for the primordial drake eggs in the area east and northeast of the camp. Burst them open and scoop up the hatchlings that come out. When the broodmother realizes what we've done, she'll have no choice but to face us.", progress = "Have you secured the bait we'll need to get the broodmother's attention?", completion = "Ah, well done. Plenty of little hatchlings for Zootfizzle over there!", objectives = "Bring 6 Primordial Hatchlings to Dorian Drakestalker at Dorian's Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12606] = { id = 12606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cocooned!", description = "Now that the tunnels have been sealed, our next concern is recovering those who have fallen to the enemy.\n\nWith any luck, several of our soldiers are still alive and relatively well inside the nerubian cocoons.\n\nFree them, {class}, while you still can!", completion = "These nerubians have taken a heavy toll, {class}.\n\nNevertheless, I am grateful for your efforts.", objectives = "Captain Rupert wants you to open the Nerubian Cocoons in Drak'Sotra and return to him once you have freed 3 Captive Footmen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12607] = { id = 12607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mammoth Undertaking", description = "Before you go off challenging Broodmother Slivina, Dorian thought it might be a good idea for you and Hemet to coordinate your efforts by riding into battle on the back of a mammoth.\n\nThe area around the camp is full of them. Just take this bridle and slip it over the head of a shattertusk mammoth. Be careful of the bulls, though. They won't tolerate the harness at all. Bring the mammoth back here when you've found a suitable one.", completion = "Perfect! Now, all we need to do is get Hemet a stepladder...", objectives = "Bring a Shattertusk Mammoth to Zootfizzle at Dorian's Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12608] = { id = 12608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultist Incursion", description = "<It appears the Avatar of Freya was right.  The undead were not able to enter Sholazar Basin before the Lifeblood Pillar was brought down -- they used their living agents from the Cult of the Damned instead.>\n\n<You'd best warn her about the Lich King's living agents within Sholazar Basin.>", completion = "The living... willingly serve the Lich King?\n\nAll this time I've been searching for the wrong enemy, {race}.  Let us make haste and uproot these cultists from these lands.", objectives = "Speak to the Avatar of Freya at the Rainspeaker Rapids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12609] = { id = 12609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking the Shelves", description = "Listen, {class}. I realize that it's a lot to ask....\n\nFresh spider ichor is somewhat hard to come by, even in these heavily infested regions. But Finklestein said he'd settle for no less than a vat of it, and that he needs it soon.\n\nI'll keep my men out in the field collecting reagents, but if the alchemist's order is going to be filled in time, they'll require some assistance.\n\nAs you roam the fields of Zul'Drak, keep your eyes peeled for trapdoor crawlers and bring me all of the ichor you can find.", progress = "Have you collected the reagents I need, {class}?", completion = "These look to be excellent samples, {name}.\n\nThank you for your assistance.", objectives = "Captain Arnath in Heb'Valok asked you to collect 7 units of Fresh Spider Ichor from the Trapdoor Crawlers in Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12610] = { id = 12610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clipping Their Wings", description = "Ever since Finklestein's arrival, I've been relegated to collecting various ingredients for his experiments and recipes.\n\nI'll follow my orders as I've vowed to do, but I'm a seasoned veteran. I've taken part in dozens of conflicts. I'd much rather be on the front lines, having a more direct impact on the Crusade's outcome here.\n\nHelp me, {race}. Collect some bat wings for me so that I might get back to the real action sooner.", progress = "Have you finished collecting those bat wings for Finklestein?", completion = "Excellent work, {name}.\n\nI thank you for your assistance.", objectives = "Captain Arnath in Heb'Valok has asked you to collect 7 Unblemished Bat Wings from Zul'Drak Bats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12611] = { id = 12611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returned Sevenfold", description = "The agents of the Lich King have foolishly trespassed upon these lands where the power of life rules supreme.  All harm they inflict will be returned to them sevenfold.\n\nThe monster directly responsible for corrupting the land is known as Thalgran Blightbringer; you will find him just to the north of here.  Take this ward and use it to reflect the power of death upon him.  Show the Scourge that the power of life prevails above all.", progress = "Is it done, {name}?", completion = "You continue to prove yourself, {name}.  Perhaps I was too quick to judge you.\n\nI had assumed you were here with the poachers who were recently stranded in my lands, but perhaps you're ready to put that behind you.", objectives = "The Avatar of Freya wants you to defeat Thalgran Blightbringer by using Freya's Ward to reflect his Deathbolts back to him sevenfold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12612] = { id = 12612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Pillar", description = "The titans shaped entire life forms here, fostering their unfettered growth.\n\nThe five crystal pillars that surround the basin emanate pure lifeforce.  The Scourge should've never been able to penetrate the basin, but one of the pillars was destroyed.\n\nGo to the Lifeblood Pillar and see if you can find out what happened.  No undead would've been able to approach the pillar, so keep your eyes out for living intruders.  You'll find what remains of the pillar directly south of here.", completion = "<The corpse is badly burnt.  There appear to be the remains of several powder kegs in the vicinity.>", objectives = "Travel to the Lifeblood Pillar and look for clues to its destruction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12613] = { id = 12613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering the Waygate - The Makers' Overlook", description = "We cannot stop now, {race}.  You've triggered the first switch, but one remains.\n\nThe titans constructed a second vantage point where they oversaw their creations.  You'll find it to the east, high in the mountains.\n\nPull the activation switch theta inside the overlook and the waygate will open.", completion = "The waygate is active, {name}.  It is time!", objectives = "The Avatar of Freya wants you to head to the Makers' Overlook in eastern Sholazar Basin and use the Activation Switch Theta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12614] = { id = 12614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Post-partum Aggression", description = "Broodmother Slivina's likely to be a snarling ball of teeth, spikes, and talons. You've gone and stolen her children away and no mother takes kindly to that.\n\n'Tis true they hatched from eggs, but she loves the little beasts no less than your mother loves you.\n\nShe'll be desperate and fierce in equal measures, everything Hemet loves in a target. You and he, along with that mammoth, should be a match for her.\n\nShe's on her perch at the northern edge of the Savage Thicket and hungers for revenge.", progress = "Well, you're alive. How did you fare?", completion = "Well, I had a whole speech prepared, but the old man himself has some words he wants to say to you.", objectives = "Kill Broodmother Slivina and return to Dorian Drakestalker at Dorian's Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12615] = { id = 12615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of Zim'Torga", description = "Hexxer Ubungo probably told you about making offerings to the gods of Zul'Drak. Zim'Abwa is not the only god that stands forgotten by the Drakkari.\n\nWe have taken refuge within the presence of Zim'Torga, the Mother of Prosperity. As with Zim'Abwa, if you were to give offerings of the Drakkari to her, she is sure to give you her blessing.", progress = "<You can feel the eyes of the Mother of Prosperity upon you. She is wondering what a {race} such as yourself is doing standing before her.>", completion = "<Zim'Torga's thoughts pervade your own. She senses the offerings you are about give to her and is pleased.>\n\n<She conveys that you will be appropriately rewarded.>", objectives = "Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Torga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12616] = { id = 12616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chamber of Secrets", description = "Excellent, an experienced adventurer. Precisely what we need.\n\nThere has been talk from the Kirin Tor guarding Medivh's tower that something is amiss with Karazhan. There is a new power lurking within, one that answers neither to the Guardian's magic nor the Legion. From what they've scouted, it appears it is an elven prince called Tenris Mirkblood, and there is reason to believe he serves the Scourge.\n\nGo, my friend, investigate Mirkblood's chamber, and return with any information you might find.", objectives = "The Argent Dawn Emissary wants you to search the chamber of Tenris Mirkblood within the Servant's Quarters of Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12617] = { id = 12617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exterminate the Intruders", description = "I am an embodiment of but one aspect of Freya, daughter of the titans.  I am the Lifewarden -- I was left here to protect this land against the threat of the Scourge.\n\nI never anticipated the Lich King would send willing living servants to do his work.\n\nI could easily crush these cultists myself, but I am all that stands between the undead armies and the rest of the basin.  Go, {name}.  Deliver my wrath to these insolent trespassers.", completion = "You speak the truth.  The intruders at the camp were dealt with... but I'm afraid it might have been too late.", objectives = "The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Death's Hand Encampment to the northwest and slay 8 Cultist Infiltrators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12618] = { id = 12618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Zim'Torga", progress = "<Zim'Torga looks on impassively. She wonders if you seek her continued blessing by presenting more Drakkari offerings to honor her.>", completion = "<The Mother of Prosperity beams her approval down upon you.>" }
quests[12619] = { id = 12619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emblazoned Runeblade", description = "The single most important piece of equipment to a death knight is the runeblade. It is through the runeblade that a death knight commands the powers of frost, blood and the unholy. The runeblade also acts as a vessel to store the death knight's runic power.\n\nThe time has come to create your first runeblade. Search the weapon racks on this floor and locate a battle-worn sword. Once found, take the sword to a nearby runeforge and use it to create a runeblade.", progress = "The runeblade is an extension of your being. A {class} cannot battle without a runeblade.", completion = "Well done, {name}. You have successfully created your first runebladed weapon. With it you will sow the seeds of chaos and destruction! In your wake will be a bloodied field of battle, littered with the corpses of all that would dare oppose the Scourge.", objectives = "Search the weapon racks in Ebon Hold for a Battle-worn Sword and then use it on a runeforge to craft a Runebladed Sword.\n\nReturn the Runebladed Sword to Instructor Razuvious in Ebon Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12620] = { id = 12620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lifewarden's Wrath", description = "We were not quick enough, {name}.  The cultist scum have arrived at the Glimmering Pillar and are making preparations to destroy it, I can sense them.\n\nWe don't have much time.  Blow upon this horn atop the Glimmering Pillar to channel my power through the crystal.\n\nWe shall show this scum to not trifle with the titans' creations.", progress = "Have you taken care of the cultists, {name}?", completion = "Impressive.  I wasn't expecting a mere mortal to prove as worthy an ally as you.\n\nI fear our efforts have not been sufficient, however.  The Scourge shows no signs of stopping.", objectives = "The Avatar of Freya at the Rainspeaker Rapids wants you to use Freya's Horn atop of the Glimmering Pillar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12621] = { id = 12621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freya's Pact", description = "The cultists have been taken care of, but the Scourge's invasion has not slowed down.  The situation is becoming desperate, {name}.\n\nThere exists a last resort.  Before I reveal any more, however, I must be sure I have your absolute trust.", progress = "We have little time.  The Scourge is preparing for a final push.", completion = "There is no turning back now.  If you agree to help me, you will do so without hesitation.", objectives = "Listen to what the Avatar of Freya has to say.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12622] = { id = 12622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leaders at Jin'Alai", description = "You thinkin' what Ahunae thinkin', mon?\n\nSome of the Drakkari trolls have gathered at the Pools of Jin'Alai to the southwest. We be needin' to draw out their leaders, and Ahunae knows just how you be doin' it, too!\n\nGo in there and kill those trolls. When you kill enough, their leaders show up.\n\nWhen they show up next to their totems, you make sure to be gettin' the treasure of Kutube'sa, Gawanil, and Chulo the Mad, mon.", progress = "The {class} must be back talkin' to Ahunae because the {class} has all that treasure.", completion = "The scalper thinkin' that you be his kind of {race}!\n\nWhat's these candybars doin' in here? What we do with this, mon?\n\nAhunae say that you can have them back!", objectives = "Scalper Ahunae at Zim'Torga has asked you to retrieve the Treasure of Kutube'sa, the Treasure of Gawanil, and the Treasure of Chulo the Mad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12623] = { id = 12623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Witch Doctor", description = "We Zandalari could use your help, {name}. We must put an end to what the Drakkari are doing to their gods!\n\nTo the northeast, up the great steps that lead to the next tier of Zul'Drak, lies Zim'Torga. It is the home to another of the god statues and a refuge that my people are desparately attempting to defend.\n\nI would like for you to travel there and speak to Witch Doctor Khufu. Be warned though, the place is under constant attack from the Drakkari.", completion = "Greetings to you, {class}. I am glad to hear that Ubungo found someone that he could trust.\n\nWelcome to Zim'Torga.", objectives = "Speak with Witch Doctor Khufu at Zim'Torga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12624] = { id = 12624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Could Be Anywhere!", description = "When I found out that Miss Boulian was helping Nesingwary with his expedition, I signed up as a deckhand immediately.  You see, I'd been meaning to marry her for months!\n\nI had it all planned out.  I was going to propose the very night of the shipwreck... but now the ring is gone.  I've searched everywhere!\n\nI know it might sound crazy, but I know the engagement ring is in the Basin.  If some Venture Company didn't steal it, maybe a wild creature ate it.  But it's here somewhere... I just know it!", progress = "The ring, {name}!  Please... tell me you've found it!", completion = "You did it!  You actually found it!\n\nI don't know... I don't know how to thank you!", objectives = "Look for a Golden Engagement Ring on the various creatures in Sholazar Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12625] = { id = 12625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dominion Over Acherus", description = "Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold.\n\nThough your thoughts may still be hazy, we haven't a moment to spare. You must claim dominion over Acherus and your mind! The horns of war surge!\n\nTake the stairs on this floor - located north, south, east and west - to the garrison floor above us. Seek out Master Siegesmith Corvus and acquire his status report. It must be delivered to Thalanor.", sourceObjective = "Report to Master Siegesmith Corvus on the garrison floor of Ebon Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[12626] = { id = 12626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Company of the Damned", description = "<Corvus salutes.>\n\nOur stockpiles of weapons, armor and munitions are nearly at maximum capacity. We are ready for war!\n\n<Corvus rolls up a fleshy piece of vellum.>\n\nOn the other side of this garrison floor, southwest of here, you will find the officers' quarters. Take this status report there and deliver it to Scourge Commander Thalanor, battalion commander of the Company of the Damned.", objectives = "Deliver Corvus' Report to Scourge Commander Thalanor at the garrison floor of Ebon Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12627] = { id = 12627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Through Jin'Alai", description = "I have been trying to commune with the gods. However, the medicine men at the Pools of Jin'Alai are performing rituals that are interfering with my attempts.\n\nIt is imperative that we break through their obtrusion. If you were to head southwest into the pools area, I am certain that you would come across the cauldrons they are using for their magic.\n\nDisturb each of the cauldrons to bring down their ritual that is blocking me.", completion = "Yes, I can already feel the difference. Thank you.\n\nLet us see if we can make contact with the gods now.", objectives = "Witch Doctor Khufu at Zim'Torga has asked you to disturb the Blue Cauldron, Green Cauldron, Purple Cauldron, and Red Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12628] = { id = 12628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Speak With Har'koa", description = "The gods have spoken, {name}. We now know what you must do.\n\nYou must now go to the Altar of Har'koa to the southeast and speak with the leopard goddess.", completion = "Listen closely, little {race}. Time is of the essence.", objectives = "Speak with Har'koa at the Altar of Har'koa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12629] = { id = 12629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can Run, But You Can't Hide", description = "Once the Scourge have a target in their sights, they'll stop at nothing to acquire it.\n\nYou're doomed to a mindless existence as a walking corpse....\n\n<Stefan's face twists into a cruel grin.>\n\n... unless we can use their desires against them.\n\nI'll explain later. I have complex magic to prepare which requires certain material components.\n\nTravel due east of here to the Reliquary of Agony. Slay abominations and gather the ghoul drool you'll find there then return to me with their remnants.", progress = "Have you brought me the components I asked for, {name}?", completion = "<Stefan sifts through the foul components.>\n\nWell, it's far from perfect, but it'll have to do. Now brace yourself, {class}. This is where it gets good....", objectives = "Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12630] = { id = 12630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kickin' Nass and Takin' Manes", description = "Before you meet Nass, there's something you should know.\n\nHe got a toxic dose of blight back in the day, and now he's deaf, blind, and mostly numb.\n\nIt's not all bad, though. He's virtually immune to the stuff now, which makes him perfect for certain tasks - like the one I'm about to give you.\n\nThere are many freshly scourged trolls nearby and we need to study the blight's effect on them. Take Nass, and this boot. When you've slain a troll, give him a good kick and he'll know to take a hair sample.", completion = "You know, you remind me an awful lot of my Nass.\n\nMaybe it's just the nose...", objectives = "Stefan in Ebon Watch wants you to use Nass to collect 10 hair samples from Withered Trolls.\n\nIf you lose Nass, return to Stefan to recover him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12631] = { id = 12631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Invitation, of Sorts...", description = "Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.\n\nGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.\n\nIf anyone can explain this, a death knight can....", completion = "I am indeed familiar with items such as this.\n\n<Stefan looks you in the eye.>\n\nIt would seem, {name}, that you have been... chosen.", objectives = "Take the Unliving Choker to Stefan at Ebon Watch.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12632] = { id = 12632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "But First My Offspring", description = "I am the last of the gods to be subdued, so we must first attempt to free the others. Bound by the magics of my subduers, I am unable to discern their fates.\n\nBut first, I would ask that you do me a kindness. Already the Drakkari turn my magic against me. They have transformed my offspring into monstrosities.\n\nTake one of my whiskers. Slay my tortured children and use the magic of it to release them from their nightmare, and bring them back to life.", progress = "There are more of my offspring that you must free from their torment!", completion = "Thank you, {name}. I will never forget what you have done.", objectives = "Har'koa has asked you to use her whisker on the corpses of her children to free and resurrect them. Return to her at the Altar of Har'koa when you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12633] = { id = 12633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkness Calling", description = "Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.\n\nGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.\n\nIf anyone can explain this, a death knight can....", completion = "I am indeed familiar with items such as this.\n\n<Stefan looks you in the eye.>\n\nIt would seem, {name}, that you have been... chosen.", objectives = "Take the Writhing Choker to Stefan in Ebon Watch.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12634] = { id = 12634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Make Lemonade, Some Make Liquor", description = "Life's tossed me a cartload of lemons this time! When the ship ran aground, the kegs carrying my best brew burst! All we have now are a few bottles of rum, and it won't sustain a thirsty expedition!\n\nWe need to get some booze cooking, and fast!!\n\nThe trees in the Wildgrowth Mangal, to the east, seem laden with fruit, but it's too high for me to reach. Look for good, strong vines, see if you can use it to shake some of that fruit out of the trees. Bring me whatever you can find.", progress = "Did you have luck winning any of that fruit from those darn tall and stingy trees?", completion = "Well, that's a better assortment than I would've expected from this place. Now, for the important question: can we distill it into anything drinkable? We'd better get started.", objectives = "Bring 1 Orange, 2 Banana Bunches, and 1 Papaya to Grimbooze Thunderbrew at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12635] = { id = 12635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Snow Leopard Goddess", description = "I overheard that you are going to see to the well-being of Har'koa. Good luck to you.\n\nI am wondering if while you are in the vicinity of the altar, you would be willing to recover their relics? I do not require many, and it is only a short trip to the southeast.\n\nWhat do you say?", progress = "The Drakkari are so busy destroying themselves, it would be a shame if the historical significance of their empire were to be likewise lost.", completion = "Aw, prime specimens!\n\nYou can see there the divergence from the root symbology. Quite extraordinary.\n\nWhat a pity that the ice trolls are determined to bring about their own demise.\n\nDid you know, for instance, that the Drakkari were exiled from the rest of the troll nations for their extremely violent ways?\n\nIt's true! How did you think trolls ended up in such a harsh climate as this?", objectives = "Chronicler To'kini at Zim'Torga wants you to recover 10 Har'koan Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12636] = { id = 12636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye Of Acherus", description = "Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold. Looming above the face of the necropolis is the all-seeing eye of Acherus. From it the master is able to see great distances into the territories held by our enemies. What the eye sees, the Lich King sees, and now the time has come for you to peer through the eye! The Lich King has called for you, {name}.\n\nGo now! Suffer well, <brother/sister>...", completion = "The time to spill the blood of our enemies approaches. You must first learn what it is that you seek to destroy, before rushing headlong into battle. It is what separates a {class} from a mindless ghoul.\n\nI will grant you sight beyond sight, my champion. You will use the eye of Acherus to steal our enemies' secrets.", objectives = "Report to the Lich King in Ebon Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12637] = { id = 12637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Near Miss", description = "It was either wisdom or luck that prevented you from wearing this choker, {race}.\n\nEither way, your acquiring it was no random occurance. You've been targeted by someone, or something....\n\nTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.", progress = "Yes, {race}?", completion = "Now you've observed the fate that was meant to befall you.\n\nAs I mentioned before, this was no coincidence. The creation of such a device is very involved, and the required resources would not be squandered on a random target.\n\nThe simple truth of the matter is this; You're wanted by the Scourge....", objectives = "Stefan at Ebon Watch wants you to take the Unliving Choker to Bloodrose Datura.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12638] = { id = 12638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close Call", description = "It was either wisdom or luck that prevented you from wearing this choker, {race}.\n\nEither way, your acquiring it was no random occurence. You've been targeted by someone, or something....\n\nTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.", progress = "Yes, {race}?", completion = "Now you've observed the fate that was meant to befall you.\n\nAs I mentioned before, this was no random act. The creation of such a device is very involved. You've somehow caught the attention of the Scourge leadership.\n\nThe question is not how, why, or even who... but what will we do about it?", objectives = "Stefan at Ebon Watch wants you to take the Writhing Choker to Bloodrose Datura.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12639] = { id = 12639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frozen Earth", description = "We captured these elementals from nearby, and I have plenty of defenders now. But, it takes a great deal of power to make them strong enough to stand up to our enemies.\n\nThe frozen earth at Drak'Mabwa to the northwest have what I need to maintain our defenses. I'll need more of their essence if I'm to keep this up.", progress = "I hope that you've returned with enough. The attacks from the Pools of Jin'Alai have become more desperate after what you did to them.", completion = "Thank you, {class}. Those essences should be enough to fuel my casting for quite some time.", objectives = "Element-Tamer Dagoda at Zim'Torga wants you to collect 7 Essence of the Frozen Earth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12640] = { id = 12640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Rifts", description = "Dagoda gonna be sendin' you northwest to Drak'Mabwa to get her more stuff for her defenders if she didn't already.\n\nWhile you up there, Ahunae be wantin' you to destroy the rifts those elementals pourin' out of. The last thing we needin' is for them to attack us!\n\nJust watch out, more of those frozen earth'll show up when you try to seal the rifts.", completion = "Ahunae hopin' that Dagoda got all of the defenders she wantin'. With those rifts sealed, it's not likely she'll be gettin' any more.", objectives = "Scalper Ahunae at Zim'Torga has asked you to seal 7 Elemental Rifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12641] = { id = 12641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Comes From On High", description = "Towering above this platform is the eye of Acherus. From it you will call forth a probe that you will then use to analyze Scarlet Crusade fortifications at New Avalon. The eye has a host of powers that should make the acquisition of this data simple.\n\nUse the eye's siphon to analyze the forge, town hall, hold, and chapel. The eye's control mechanisms are located on either side of this platform. Waste no more time, {name}.\n\nThe Scourge will have this place. The Lich King commands it!", progress = "Our assault upon the Scarlet Crusade will become legend.", completion = "They prepare for battle - as expected - but there is something else. I sense an old enemy. An enemy that I destroyed long ago...\n\nIt matters not. We will send the full might of the Scourge against them before they have a chance to evacuate their homes and put in place their defenses.", objectives = "The Lich King commands you to use the Eye of Acherus to analyze the Scarlet Hold, New Avalon Forge, New Avalon Town Hall and the Chapel of the Crimson Flame.\n\nControl the Eye of Acherus by using the Eye of Acherus Control Mechanism.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12642] = { id = 12642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of Rhunok", description = "My feelings tell me that Rhunok doesn't have much time.\n\nI can tell that the arctic bear god's spirit has already separated from his weakened body. It is his spirit with which you must commune.\n\nHis altar lies to the northwest beyond Drak'Mabwa.", completion = "I am barely hanging on. You must work quickly or all will be lost.", objectives = "Speak with the Spirit of Rhunok at the Altar of Rhunok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12643] = { id = 12643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Lining", description = "Once the Scourge have a target in their sights, they'll stop at nothing to acquire it.\n\nYou're doomed to a mindless existence as a walking corpse....\n\n<Stefan's face twists into a cruel grin.>\n\n... unless we can use their desires against them.\n\nI'll explain later. I have complex magic to prepare which requires certain material components.\n\nTravel due east of here to the land beneath the Reliquary of Agony. Slay the ghouls and abominations you'll find there and return to me with their remnants.", progress = "Have you brought the components I asked for, {name}?", completion = "<Stefan sifts through the foul components.>\n\nWell, it's far from perfect, but it'll have to do.\n\nNow brace yourself, {class}. This is where it gets good....", objectives = "Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12644] = { id = 12644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still At It", description = "Now that we've got the raw materials, I've had my assistant ready the still. He'll oversee the process, but I want you to help keep everything under control. You might be tempted to think that we just throw everything into the still and let it sit, but you're wrong.\n\nIngredients and heat need to be added at certain times, and the pressure regulated at others. You'll have no more than 10 seconds to react to a situation. Speak with \"Tipsy\" McManus when you're ready to start distilling.", progress = "Well, how did it turn out?", completion = "<Grimbooze gives the cask a shake.>\n\nThere's something in here, but the million gold question is, can you drink it? Don't you go anywhere; you'll be responsible for overseeing the sampling of the product, too.", objectives = "Successfully complete the distillation process and bring the completed Thunderbrew's Jungle Punch to Grimbooze Thunderbrew at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12645] = { id = 12645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taste Test", description = "And now for the moment of truth!\n\n<Grimbooze chuckles.>\n\nI've always wanted to say that. Normally, I'd debut a new drink at a banquet, but we can't have one in the middle of the jungle.\n\nInstead, just take samples to a few trusted friends and return with their comments. Let's see, we'll definitely want Hemet Nesingwary's opinion, and Hadrius Harlowe's, too. They're here in camp. You'll want to head over to Lakeside Landing, near the center of the Basin and offer Tamara Wobblesprocket a taste.", completion = "Two out of three drinkers agree, eh? Not bad for a first try. Not bad at all. I suppose I'll have to whip up something else for Tamara by way of apology.\n\nNow... what should we call this creation?", objectives = "Offer a sample of Thunderbrew's Jungle Punch to Hemet Nesingwary, Hadrius Harlowe, and Tamara Wobblesprocket, then return to Grimbooze Thunderbrew at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12646] = { id = 12646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Prophet, My Enemy", description = "My prophet absorbed too much of my power too quickly, and subsequently killed himself. You can see the results at the water-filled crater to the south in Drak'Mabwa.\n\nMy former priests have already resurrected him so that he can finish the job. They're channeling my power back into him, and it will not be long now before he reawakens.\n\nYou must put an end to him and return with my mojo before it is too late.", progress = "Quickly, {race}, do you have my mojo?", completion = "You did it.\n\nBut now there is one other thing that I need you to do.", objectives = "The Spirit of Rhunok at the Altar of Rhunok has asked you to acquire his Arctic Bear God Mojo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12647] = { id = 12647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End to the Suffering", description = "My body is too far gone now, {name}. It is only a matter of time before a new prophet is elevated and finishes what the other began.\n\nI am going to imbue you with the last of my power. The tormentor inside the altar building carries incense, which will awaken my body and make it vulnerable.\n\nUse the incense and do me the kindness of putting an end to my suffering.\n\nI apologize if I fight back. Even for me, the will to survive is strong.", progress = "If you do not put an end to my suffering soon, {name}, all may be lost.", completion = "You've done what had to be done and honored me in the process.\n\nI give you my deepest thanks, {name}. I only hope that you and Har'koa will be able to help the others.", objectives = "The Spirit of Rhunok has asked you to use the Tormentor's Incense to awaken his body. You are then to slay Rhunok using the power that his spirit has imbued you with.\n\nIf for some reason you lose the Mojo of Rhunok aura, you can return to the Spirit of Rhunok to have it reapplied.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12648] = { id = 12648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressing Down", description = "There... I've created a disguise that should make you indistinguishable from the Scourge.\n\nYou'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!\n\nAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.\n\nLet's test it out. Use the choker and visit the Scourge merchant just east of here. Return to me with a bottle of bitter plasma.", progress = "Well, {name}?\n\nDid you purchase that flask?", completion = "So? How are you enjoying scourge life?\n\nBelieve me, it's not all it's cracked up to be....", objectives = "Stefan at Ebon Watch wants you to use the Ensorceled Choker to apply the Scourge disguise.\n\nWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12649] = { id = 12649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suit Up!", description = "There... I've created a disguise that should make you indistinguishable from the Scourge.\n\nYou'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!\n\nAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.\n\nLet's test it out. Use the choker and visit the Scourge vendor just east of here. Return to me with a bottle of bitter plasma.", progress = "Well, {name}?\n\nDid you purchase that flask?", completion = "So? How are you enjoying Scourge life?\n\nBelieve me, it's not all it's cracked up to be....", objectives = "Stefan at Ebon Watch wants you to use the Ensorcelled Choker to apply the Scourge disguise.\n\nWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12650] = { id = 12650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plundering Their Own", description = "There is another altar nearby where there are artifacts to be saved.\n\nIt is said that the Drakkari at the Altar of Rhunok to the northwest, beyond the broken tundra of Drak'Mabwa, have already plundered their own holy site.\n\n{class}, I would be appreciative if you could rescue those artifacts from their undeserving hands.", progress = "There is no comprehending the Drakkari. They are brutal savages who have sunk to a new low.", completion = "Let me look at those.\n\n<The chronicler examines the artifacts that you have recovered.>\n\nHmph, I'd say that we're lucky you liberated these when you did, {class}.\n\nHow very interesting. This artifact here depicts the events of the Sundering. There was a time when Northrend was the far northern portion of Kalimdor.\n\nBut after the Sundering, the land broke off, eventually becoming Northrend.\n\nThis, of course, is why we see Drakkari in the southern continents as well as here.", objectives = "Chronicler To'kini at Zim'Torga wants you to recover 7 Rhunokian Artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12651] = { id = 12651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lakeside Landing", description = "When the trouble with the Venture Company started, I asked Marvin Wobblesprocket and his wife, Tamara, to take their flying machines east to River's Heart. I asked them to setup a small camp there so that we could use them as a relay to fly in supplies and survey the area.\n\nThey should have arrived by now and started setting up. River's Heart is near the center of the basin where the rivers converge. Search for Lakeshore Landing on the northeast shore. Marvin mentioned it would be the best spot.", completion = "So, Hemet sent you? We were just about to let him know that we've gotten things up and running here. Please forgive Marvin if he seems to be ignoring you, but he gets very absorbed in his work.", objectives = "Speak with Tamara Wobblesprocket at Lakeside Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12652] = { id = 12652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feedin' Da Goolz", description = "Git o'er heer, gool! Yeh, I talkin' to yoo.\n\nIt feedin' time now. Gotta git da grub ta all da gools!\n\nSpeshal grub dis time! Bowels an' brainz bowl... num, num, num.\n\nJus drop da bowl nexta da gool. Gud way ta make frenz.\n\nYoo got goolfrenz? Ha, ha, hah!", completion = "Num num!", objectives = "Gristlegut at the Reliquary of Agony wants you to use Bowels and Brains Bowl next to 10 Decaying Ghouls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12653] = { id = 12653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Har'koa", description = "And now it is time for you to return to the leopard goddess. Somehow I sense that she has other plans for you.\n\nTell her that no matter what, we are eternal.", completion = "<The cat goddess howls in pain.>\n\nMy spirit cries out in grief at the loss of another friend. But fear not, he will return and his spirit will live on forever.", objectives = "Speak with Har'koa at the Altar of Har'koa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12654] = { id = 12654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Part-time Hunter", description = "When Hemet asked me to accompany Marvin out here, I hoped that I might have the opportunity to work on my own hunting skills in between repairing the flying machines and setting up the camp.\n\nI wanted to take down a ferocious lion named Pitch. He's said to make his home south of here, near where the Wildgrowth Mangal meets the northern face of the Skyreach Pillar. If you can find the beast, would you bring back his remains? If the rumors are true, they'd make a trophy even Hemet will respect!", progress = "Did you find Pitch?", completion = "You got it! Now all I have to do is make a trophy out of it. That'll be the hard part -- finding a way to preserve it so that Hemet doesn't have a good laugh at my expense.", objectives = "Bring Pitch's Remains to Tamara Wobblesprocket at Lakeside Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12655] = { id = 12655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of Zim'Rhuk", description = "There is another god of Zul'Drak that is being neglected.\n\nZim'Rhuk's statue lies directly to the north. Known as \"The Wise One\", Zim'Rhuk is also known to be very protective of his domain. He maintains guardians that deal harshly with anyone that does not have the wits to slip past them.\n\nAvoid the guardians and give the Drakkari offerings to Zim'Rhuk so that you will benefit from his blessing.", progress = "<You sense that Zim'Rhuk does not trust you. He is attempting to call out to one of his guardians.>", completion = "<Zim'Rhuk acknowledges the offerings you intend to place before him, though he knows that you took them from the corpses of others.>\n\n<If you give the offerings to him, he reluctantly agrees to grant you his blessing.>", objectives = "Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Rhuk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12656] = { id = 12656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Zim'Rhuk", progress = "<Zim'Rhuk is impressed and frustrated that once more you seem to have dodged his guardians. At least for now.>\n\n<Place the offerings before him and he will grant you his blessing again.>", completion = "<Zim'Rhuk forces an image into your mind of one of his guardians squishing you beneath its foot. Perhaps you should attempt to appease Zim'Rhuk with more offerings.>" }
quests[12657] = { id = 12657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might Of The Scourge", description = "Listen well, death knight, for I give to you the words that will start a war. My final judgment has been passed: Death. To. All. None shall stand so boldly against the might of the Scourge without reprisal!\n\nAs you have served me well in your first task, so too shall you serve me in your next task. Take my judgment to Highlord Mograine at the command post of Acherus, found on the first floor. Tell him to begin the assault.\n\nAnd when the Crusade has been dealt with, we will finish off the Argent Dawn.", completion = "The horns of war will soon echo across this land, waking the dead and calling forth the Scourge war machine. Woe unto those that would stand in our way!\n\nYou and your brethren will lead the charge, {name}. When next I look upon the Scarlet lands, my sight will be obscured by the legions of Acherus. The march upon New Avalon begins now.", objectives = "The Lich King commands you to carry his orders to Highlord Darion Mograine at Ebon Hold.\n\nUse the glowing transporter behind The Lich King to reach Highlord Darion Mograine in the Hall of Command.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12658] = { id = 12658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Pet Roc", description = "Dorian's had me training and feeding the baby drakes he captures, and it has gotten me thinking. I want a pet of my own!\n\nNo, not a juvenile drake. I don't want a pet capable of biting my hand off!\n\nHowever, in the Bonefields to the northeast of the camp, beyond the area dominated by the drakes, there's a large population of goretalon rocs. The grown ones are beyond hope of domesticating, but if you bring me the eggs from their nests, I can raise them from the time they hatch.", progress = "Do you have those eggs?", completion = "Oh, these are very nice! I've gotten so tired of robotic squirrels and chickens for company. It'll be wonderful to have a pet whose joints won't require oiling!", objectives = "Bring 7 Roc Eggs to Zootfizzle at Dorian's Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12659] = { id = 12659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalps!", description = "I thinkin' it be time to do some scalpin', mon!\n\nThe trolls at Heb'Drakkar to the northeast should do nicely. With their fancy bats and attackin' us, they got it comin'!\n\nAhunae even give you his own knife so that you do the job right.", completion = "Aw, me thinkin' that too funny.\n\n{name} is my kind of {race}!\n\nYou still got my knife?", objectives = "Scalper Ahunae at Zim'Torga wants you to use Ahunae's Knife to scalp 10 Heb'Drakkar trolls.\n\nThe scalper reminds you that you should loot them first.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12660] = { id = 12660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Destruction", description = "The Lich King's lackeys have dared to bring weapons of destruction into my domain.  I will not stand for this.\n\nGo to their outpost to the north and destroy the weapons they would use against the land.  We cannot let the Scourge taint another inch of these sacred lands.", completion = "I thank you, {race}.  You're proving to be a worthy ally.", objectives = "The Avatar of Freya wants you to go to the Death's Hand Encampment to the northwest and destroy 4 Unstable Explosives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12661] = { id = 12661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Voltarus", description = "By now you've probably guessed the details of my plan.\n\nWe're using the Scourge's interest in you against them. You're going undercover. I know it's likely a death sentence, but if we do nothing your death is a certainty.\n\nTravel northeast to Reliquary of Pain and stand on the platform while wearing your disguise. Once inside Voltarus, you must earn the trust of the Scourge commander.\n\nWhen you've completed your mission, blow this horn and I'll fly to your location to receive your report.", completion = "Well, now... I must admit I'm more than a little surprised to see you, {name}.\n\nTell me what you've learned.", objectives = "Stefan wants you to use your Ensorcelled Choker to get into Voltarus and do whatever the Scourge leader there asks of you.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12662] = { id = 12662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing Down Heb'Jin", description = "<Dagoda looks at Ahunae and sighs.>\n\nYou want to really deal with Heb'Drakkar? Collecting scalps isn't going to get the job done. You have to take out their leader, Heb'Jin.\n\nThe problem is, he's up on the bat rookery goading his forces on.\n\nBang his drum and I guarantee that he'll fly down. That's when you kill him.\n\nYou can take this net we got from one of his headhunters. Use it to trap his bat when he lands. That way you won't have to fight both of them.", completion = "You did it!\n\n<Dagoda gives you a big kiss on the cheek.>\n\nYou have no idea how much of a relief that is to me! Defending against trolls on all sides is really putting a strain on us. Not to mention his incessant yelling.\n\nPlease, {name}, take your pick of what we have to offer.", objectives = "Element-Tamer Dagoda at Zim'Torga wants you to kill Heb'Jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12663] = { id = 12663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reunited", description = "{name}!\n\nYa musta received mah gift! Turn around, mon, lemme get a good look at ya... Ahh, ya make me proud.\n\nWe come such a long way, you and I, and now we be servin' da Lich King together.\n\nStick with me and big things be comin, mon. Big things... but first, we need to be gettin' ya caught up. So much been happenin' since I saw ya last.\n\nGo speak ta Gorebag for a tour of Zul'Drak. Listen for me and I'll tell ya all ya be needin' ta know.", completion = "So, now ya be seein' what we be up against, mon.\n\nGo down, take some time ta learn da land, prepare some strategy. \n\nI'll be havin' some tasks for ya soon.", objectives = "Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12664] = { id = 12664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Horizon", description = "Ahh, another supplicant answerin' da Lich King's call.\n\n<Drakuru sniffs you.>\n\nFreshly scourged, eh? Ya still be reekin' of da living!\n\nLong be da line of dem who seek da Lich King's blessings. Ya must rise above da masses and prove yerself worthy of wieldin' true power.\n\nLookin' down over Zul'Drak, I sensed potential in ya. I ordered your - invitation.\n\nDa rest be up ta you....\n\nGo an' speak ta Gorebag for a tour of Zul'Drak. Dere be much ta do if you're to be of any worth to me.", progress = "Have ya taken in da battlefield yet, mon?", completion = "So, now ya be seein' what we be up against, mon.\n\nI want ya ta go down, learn da land, mingle with yer bretheren. Prepare yourself...\n\nSoon, dere be much for ya to do. Don't ya be disappointin' me!", objectives = "Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12665] = { id = 12665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Sense a Disturbance", description = "There's something wrong with Quetz'lun, the wind serpent goddess. What it is exactly I cannot sense, but I do know that her altar has been overrun with powerful creatures.\n\nI'm going to send you there on the back of one of my children, which you saved. The two of you will move swiftly and with great stealth to uncover what has become of Quetz'lun.\n\nMy child will see you safely back to me. Just keep your eyes open.\n\nWhen you are ready, ask and I will call one of my kittens for you.", completion = "Thank you for bringing my kitten back safely.\n\nDeep down I knew it. I wanted to deny it, but your eyes have revealed the truth.\n\nNevertheless, I sense something else. All is not as it seems.", objectives = "Har'koa has asked you to determine what has happened to Quetz'lun. Speak to her to be able to ride one of her children stealthily into the Altar of Quetz'lun.\n\nReturn to her at the Altar of Har'koa once you have done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12666] = { id = 12666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for the Underworld", description = "Quetz'lun may be dead, but I can still feel her spirit lingering in the underworld at the altar. We have to find a way to get you to her.\n\nLuckily for us, I just happen to have a supply of former supplicants at hand who are no longer in need of their sacred adornments. Both my subduers and claws are likely to still be wearing them.\n\nBring the adornments to me and I'll draw upon their energy to enable you to cross over into Quetz'lun's underworld nightmare.", progress = "I never imagined that it would come to this. The Drakkari are truly lost.", completion = "<The leopard goddess looks saddened at the collection of holy symbols that you have brought before her.>\n\nThere was a time when these meant something. Let's see if we can put them to better use.", objectives = "Har'koa wants you to collect 8 Sacred Adornments. Deliver them to her at the Altar of Har'koa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12667] = { id = 12667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Wind Serpent Goddess", description = "You are prepared, but I'm not certain that you're ready for what is to come.\n\nWhen you cross back over into Quetz'lun's altar area, you will enter the realm of the dead. From what I can feel of it, it's not going to be pleasant.\n\nTry not to be distracted by what you see in there. Simply head for the altar building and seek out Quetz'lun's Spirit.", completion = "{race} worm. Tell me why I should not annihilate you where you stand?", objectives = "Seek Quetz'lun's Spirit at the Altar of Quetz'lun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12668] = { id = 12668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foundation for Revenge", description = "I have something special planned for my favorite high priests. But first you get to prove yourself in laying the foundation for my revenge.\n\nYou do still want to live, yes?\n\nAs you have seen, my devotees are enjoying their stay here, but now it's time for them to make final restitution.\n\nDo me the smallest of favors if you would, {name}. Lure them near my soul fonts and then put an end to their existences.\n\nThey taste so delicious, and their sacrifice will not go in vain, I can assure you.", progress = "Why do you return when your task is not yet complete? Do you not realize that I can destroy you with but a thought?\n\nGo now, little {race}. Complete that which I commanded of you!", completion = "Exquisite. Perhaps you will be of some use after all.", objectives = "Quetz'lun's Spirit has tasked you with the destruction of 12 trolls, either Quetz'lun Worshippers or Serpent-Touched Berserkers, near her Soul Fonts.\n\nOnly after you have accomplished this should you return to her at the Altar of Quetz'lun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12669] = { id = 12669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So Far, So Bad", description = "Everything you've reported is consistent with what we know. Learning of Drakuru and earning his trust will lay the groundwork for your future missions.\n\nReturn to him and do as he says. Do whatever you must to appear sincere, {name}. A great deal is riding upon your performance.\n\nThis time I'm adding an additional assignment: While you're in the field, pour this additive into their blight cauldrons. It should neutralize the scourging agent and render the batch useless.", completion = "Nice work, {name}!\n\nDiluting those cauldrons will not only save lives, it will slow the growth of the Scourge in this region.\n\nNow come, tell me what you've learned of Drakuru's strategy in Zul'Drak.", objectives = "Stefan at Ebon Watch wants you to return to Drakuru and complete any tasks he has for you.\n\nWhile at the Reliquary of Pain, you are to use the Diluting Additive on 5 Blight Cauldrons.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12670] = { id = 12670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Harvest", description = "Below Acherus stands Death's Breach, the staging point for our assault upon the Scarlet Crusade. You are to ride one of my Scourge gryphons, located on either side of this platform, and report to Prince Valanar. Do as he says and you may live to see these lands fall before us.", completion = "Do you smell it?\n\n<Valanar sniffs at the air.>\n\nFresh meat... The scent of Scarlet Crusader wafts through the air.\n\n<Valanar salivates.>\n\nApologies, {class}, I'm sure you're not interested in my choice of fine cuisine. You are here to work! To lead the charge! Yes... I know. The Lich King has told me all that I need to know about you, {name}.\n\nThe time for bloodshed is now.", objectives = "Report to Prince Valanar at Death's Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12671] = { id = 12671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconnaissance Flight", description = "It's about time we had planes up and running in this place.  The professor's been asking me to check out a strange weather pattern coming from the northeast.\n\nThing is, I'm going to need a co-pilot if we're going into uncharted territory.  No way in hell I'm heading out there alone.\n\nWhat do you say, <tough-guy/hotshot>?  You might learn a thing or two.  And once you learn to deal with the northern winds... you can pretty much fly anywhere.", completion = "You saved my life up there, buddy.  Nice flying!", objectives = "Help Pilot Vic complete the Reconnaissance Flight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12672] = { id = 12672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting the Stage", description = "I will give you a chance at continued existence.\n\nThere are fragments of the power that fueled my curse scattered about the altar grounds. It is my desire that you collect some of them for me. Not so many that the curse will be lifted, but enough that I will be able to eventually make use of them to exact revenge upon my prophet.\n\nGo, insect. Run and do my bidding before I change my mind about letting you live.", progress = "What a shame that Har'koa didn't send you along sooner. Then again, she and I never did get along.\n\nShe probably held back your help just long enough for this to happen.", completion = "They'll do. Likely I won't even need them.\n\nBut it was fun watching you run around at my command.", objectives = "Quetz'lun's Spirit has demanded that you collect 10 Underworld Power Fragments. Return to her at the Altar of Quetz'lun only when you have done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12673] = { id = 12673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Rolls Downhill", description = "If ya ever gonna be worthy of da Lich King's gifts, ya must learn ta be a great leader - one who be commandin' respect!\n\nI got a task dat gonna refine your command skills, mon....\n\nSumma my minions be trained ta harvest blight crystals from da land below, but dey be lazy and slow. You gonna be in charge o' dem, mon.\n\nTake dis scepter and teach 'em how to get da job done. When dey be under your control, make 'em harvest dem crystals!", progress = "Ya got my underlings whipped into shape, {name}?", completion = "Da crystals be pilin' up like never before!\n\nYou keep up da good work, {name}. I got more tasks for ya real soon.", objectives = "Overlord Drakuru in Voltarus wants you to use the Scepter of Suggestion on the Blight Geists and then order them to harvest 7 Blight Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12674] = { id = 12674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hell Hath a Fury", description = "It is now time for you to punish my three high priests: Mu'funu, Tua-Tua, and Hawinni. You'll find them spread around the altar grounds.\n\nTake this hexxing stick. I've empowered it with my rage and indignation. I'm sure that it will prove potent.\n\nJust use it and proceed to destroy them. The hex will take care of the rest.\n\n<Quetz'lun displays a toothy grin.>\n\nSucceed and I may let you go. Fail and die.", progress = "DO YOU THINK THAT I'M A FOOL?\n\nTHEY'RE NOT DEAD!", completion = "<The terrible spirit before you lets loose a blood-chilling cackle.>\n\nThey had it coming. And I'll give them more of the same again and again and again....", objectives = "Quetz'lun's Spirit at the Altar of Quetz'lun wants you to use Quetz'lun's Hexxing Stick upon High Priest Mu'funu, High Priestess Tua-Tua, and High Priest Hawinni. Once you have done this, slay them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12675] = { id = 12675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Thing", description = "There is one last thing that is needed to enact the final revenge against my prophet. The power fragments you collected must be imbued with a portion of a living gods' spirit. You're going to need to beseech Har'koa for some of hers.\n\nOnce you've done that, when you return here, you will not come to the underworld. Instead, you will return to the physical world of my altar. My children and guardians will no longer attack you, and you'll be able to get to my prophet without having to worry about them.", progress = "You've returned, {name}.", completion = "A portion of my spirit?\n\n<The snow leopard goddess pauses a moment to consider.>\n\nThat's quite an expensive gift considering that this is for revenge and I'm already greatly weakened by the actions of my subduers.\n\nStill, I may know a way.", objectives = "Deliver the Underworld Power Fragments to Har'koa and beseech her for a portion of her spirit. You will still find her at the Altar of Har'koa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12676] = { id = 12676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage", description = "While we're working to discover the purpose of these crystals, we need you back in Voltarus doing Drakuru's bidding.\n\nEvery task you perform successfully gets you closer to him, and brings us that much nearer to knowing his mind.\n\nWhile you're there, I have another mission for you. Drakuru's Scourgewagons pose a significant threat. We need them destroyed. \n\nMake your way to the wagons and activate these charges. Once they're set, get clear! The explosion will expose you if you're too close.", completion = "Excellent!\n\nYour undercover work has truly paid off, {name}.\n\nNow let's have a look at that scepter....", objectives = "Stefan at Ebon Watch wants you to perform another task for Drakuru.\n\nAdditionally, you are to use the Explosive Charges on 5 Scourgewagons at the  Reliquary of Pain.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12677] = { id = 12677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazardous Materials", description = "Blight crystals?! What could this scumbag Drakuru be up to? Clearly, he's working on something significant.\n\nContinue to do his bidding and perhaps once he's more familiar with you he'll reveal his plans. In the meantime, we need to have a look at these crystals.\n\nWhile you're in Voltarus, try to get some samples of the harvested crystals when no one's looking.\n\nBe alert! Handling those crystals can trigger your disguise to fail.", progress = "Welcome back, {name}.\n\nWere you able to steal any samples of Drakuru's crystals?", completion = "Fascinating!\n\nWe'll look into the properties of these crystals right away.\n\nNow tell me, {name}, what is the latest with this Drakuru fellow?", objectives = "Stefan at Ebon Watch wants you to go to Voltarus and complete any tasks Drakuru has for you. While there, you are to steal 5 Harvested Blight Crystals.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12678] = { id = 12678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If Chaos Drives, Let Suffering Hold The Reins", description = "They make their stand now, outside of Death's Breach, futilely attempting to push us back in hopes of saving their horses, mines, lumber and citizens.\n\nThis will be your first lesson in Scourge warfare: TERROR!\n\nGo to the front lines, south of here, and destroy Scarlet Crusaders. Leave their corpses so that we may utilize them for the death march.\n\nBut most importantly: kill the fleeing villagers. Soldiers dying are an affordance, but villagers? That is what strikes fear into the hearts of man.", completion = "Do you feel it, {name}? That sensation is raw power coursing through your body. Such a thing cannot exist for mortals.\n\nThe front lines are now dismantled. The geist will finish the job and prepare the grounds for Razuvious. We turn our attention now to more tactical targets.", objectives = "Prince Valanar at Death's Breach commands you to slay 10 Scarlet Crusaders or Scarlet Peasants and 10 Citizens of Havenshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12679] = { id = 12679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tonight We Dine In Havenshire", description = "The Sky Darkeners are mindless constructs with one purpose: KILL! Specifically, they are aiming to kill any man or woman that they see fleeing Havenshire for the safety of New Avalon. We certainly can't allow those cowards to make it to safety and then take up arms against us!\n\nThere is one slight problem. They use saronite arrows for maximum range and damage. Saronite, however, is a metal only found in Northrend, so supplies are limited! Retrieve those arrows for me and I will reward you handsomely.", progress = "The trajectories they are firing at would have most of the arrows land at or near the Havenshire Farm, south of us.", completion = "Well done, {class}! You feed the Scourge war machine with your deeds!\n\nAh yes, your reward - as promised.", objectives = "Orithos the Sky Darkener at Death's Breach wants you to recover 15 Saronite Arrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12680] = { id = 12680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Theft Palomino", description = "How fortuitous it is that the Crusade has a stable full of horses a mere stone's throw from this post. Though they guard it tenaciously, an enterprising young death knight could break through their defenses and take what is rightfully <his/hers>!\n\nOnce you acquire a horse from the Havenshire Stables, return it to me and I will see what can be done about transforming it into a proper deathcharger.\n\nRemember, {name}, it's only stealing if you're caught. Watch out for that deranged stable master, Kitrik!", progress = "You don't want to walk forever, do you?", completion = "Now for the true test. Can you show mastery over an unbound charger and brutally overtake the thing that you desire most?", objectives = "Salanar the Horseman asks that you steal a horse from the Havenshire Stables and return it to him at Death's Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12681] = { id = 12681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagent Agent", description = "That Archmage Pentarus, back in Dalaran, will be expecting us to return with all kinds of reagents and talismans. It seems the locals are fond of animal parts. Twisted claws from the goretalon rocs are among their favorite.\n\nIt's not my place to say whether the rumors are true or not, but I've a feeling there's something here.\n\nThe rocs live in the Bonefields off to the northeast, where they feed on the corpses of old mammoths. Will you help me gather talons for the archmage's research?", progress = "Were you able to find any of the twisted talons?", completion = "<Colvin looks admiringly at the talons you've brought back.>\n\nThese will more than suffice. The gorlocs have a saying that the more gnarled the talon, the more power it holds. I'm sure the archmage will get his money's worth from this expedition.", objectives = "Bring 5 Twisted Roc Claws to Colvin Norrington at Dorian's Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12683] = { id = 12683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning to Help", description = "There's no more caustic material in all of the basin than bittertide hydra sputum. I've got special containers to collect just such a thing for Archmage Pentarus' studies. Now all I need is a brave, um... collector.\n\nYou look like a hardy, adventurous {class}. How'd you like to make a bit of money and aid Dalaran's cause at the same time?\n\nAll you need to do is take this container with you to Bittertide Lake, to the southwest. Engage the hydra and use the container to sample the sputum they shower you with.", progress = "Did you get those samples?", completion = "Wonderful! Here's your payment, as agreed. And, uh, a bit of advice: you might want to enjoy long, hot baths the next few days if that 'burning sensation' persists.", objectives = "Colvin Norrington at Dorian's Outpost wants you to take 5 Hydra Sputum Samples and kill 5 Bittertide Hydra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12684] = { id = 12684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of a Dead God", description = "Mam'toth, the god of the mammoths, destroyed himself, and took much of his temple with him, rather than allowing his trolls to gain his power.\n\nIf I'm to sacrifice a portion of my spirit, I will need something with which to bolster myself.\n\nMam'toth left behind an enormous crater to the northeast, just north of the Altar of Quetz'lun. Within the crater his blood yet lives.\n\nBring it to me.", progress = "I wish that there were something that we could do to bring Mam'toth back to life, but there isn't.\n\nWe can honor him and his sacrifice by continuing the fight against the Drakkari.", completion = "Very well. Let us see if this works....", objectives = "Har'koa has asked you to collect 7 Blood of Mam'toth. Return them to her at the Altar of Har'koa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12685] = { id = 12685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Reap What You Sow", description = "This is what it has come down to... revenge.\n\n<Har'koa sighs.>\n\nTake this ritual kit and enact it near Quetz'lun's corpse upon her altar. If everything works properly, her spirit should be drawn into the material world where she will be able to reclaim her power from the prophet.\n\nThe rest will be up to you, {name}. You must slay the prophet in his drained state.", completion = "<The witch doctor shakes his head in disbelief.>\n\nIt sounds like you barely escaped Quetz'lun's underworld alive.\n\nI'm glad that it's you out there. I don't know if I would have had the courage to deal with that situation!", objectives = "Slay the Drained Prophet of Quetz'lun and then inform Witch Doctor Khufu at Zim'Torga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12686] = { id = 12686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zero Tolerance", description = "Ignorance! Dis be intolerable, mon! My entire batch of blight be useless!\n\nDat mongrel, Darmuk! He be responsible for watchin over da blight. He failed me, mon!\n\nDis be a good lesson for ya, {name}. Failure be like a disease dat spreads. Ya gotta catch it and kill it early, before it be killin' you!\n\nTake dis scepter. It make my scourged trolls stronger. Use dem ta kill Darmuk. He be lurkin' down below just to da south.\n\nLet dat be an example to all, mon. Don't be failin' Drakuru!", progress = "Has Darmuk paid for his failure, {name}?", completion = "Ya done good, {name}. You be learnin' faster than I had hoped.\n\nGo now, get ya some rest. Soon I be givin' ya an even greater test!", objectives = "Drakuru in Voltarus wants you to go to the Reliquary of Pain and use the Scepter of Empowerment on a Servant of Drakuru. You are then to use its abilities to defeat Darmuk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12687] = { id = 12687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Realm of Shadows", description = "The horse you stole has been taken to the Realm of Shadows. It is there that my dark rider will slay the beast and raise it as a deathcharger. Do you think yourself brave enough to enter the Realm of Shadows in pursuit of the deathcharger?\n\nIf you accept, I will transport you to the shadow world. Once there, seek out a dark rider in the open fields south of us. To emerge victorious you must slay him, overtake his deathcharger and return it to Death's Breach. Issue the Horseman's Call should you succeed.", progress = "You must take the deathcharger by force, {class}!", completion = "You have succeeded where most initiates fail, {name}. For that you will be rewarded handsomely.", objectives = "Salanar the Horseman at Death's Breach has challenged you to slay the Dark Rider of Acherus and take his Acherus Deathcharger.\n\nShould you succeed, return the Acherus Deathcharger to Death's Breach and use the Horseman's Call to summon Salanar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12688] = { id = 12688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engineering a Disaster", description = "These goblin goons and their minions have decided that they own this pillar and its crystals. I came here to explore the crystals and take samples, but they overpowered me and won't let me return to the camp.\n\nIf you'll help me fight our way out of here, we can teach these thugs a lesson they'll never forget!", completion = "Thank you for freeing Helice and seeing to her safe return. We all started to get worried when she didn't return from her crystal hunting trip.", objectives = "Help Engineer Helice escape from Swindlegrin's Dig, then speak with Hemet Nesingwary at the Nesingwary Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12689] = { id = 12689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand of the Oracles", objectives = "Hi! Really glad see you again!\n\nI knew we friends. I knew it! You good friend. Not just for us, but for all Oracles. Thank you for saving us! Thank you, thank you!\n\nI saw you bonk that puppy-man good! Undead thing said he your friend before? I not know that. You done with puppy-men though, yeah? Just Oracle friend now?\n\nStop! No agree without thinking - you sure you not want to be friends with puppy-men anymore?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12690] = { id = 12690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuel for the Fire", description = "It be time we start our march to Gundrak, mon. It be time for me ta turn ya loose on dem trolls!\n\nDey breached our wall and put a whole army just north of us.\n\nHahaha!\n\nDey be fuel for da fire, mon! We gunna take da chieftiains an' kill da rest! It all be part of my master plan....\n\nYou take dis scepter and go command my abominations. Bring 'em to da Drakkari army and kill em all! When da chieftains come, my pet Shalewing gunna snatch 'em up and bring 'em here to me.", progress = "Did ya smash da trolls, {name}?", completion = "We done it, mon!\n\nI got da chieftains all caged up and you led my abominations to victory over their armies.\n\nIt be time ta celebrate, mon!", objectives = "Drakuru in Voltarus wants you to use the Scepter of Command on Bloated Abominations and then use their abilities at the Frigid Breach to kill 60 Drakkari Skullcrushers and lure out 3 Drakkari Chieftains.\n\nChieftains will appear when enough Skullcrushers have been slain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12691] = { id = 12691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Timeworn Coffer", description = "The stone coffer appears to be locked.  It appears that a key fits inside a large stone keyhole.\n\nPerhaps one of the guardians in the vicinity has this key in its possession.", progress = "The stone coffer does not budge.", completion = "The huge stone key turns with a deep grunt as the coffer lid opens up to reveal hidden treasure inside.", objectives = "Obtain a Huge Stone Key from the nearby Sholazar Guardians and bring it to the Timeworn Coffer at the Maker's Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12692] = { id = 12692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Lich Hunter", description = "Okay, I going back to Frenzyheart Hill to make sure all Frenzyheart know what you done for wolvar and for Zepik. You great hunter and they dumb to think you not.\n\nGo back to hill and talk to Elder Harkek... I make sure he knows you not traitor before any other Frenzyheart.\n\nThank you, Lich Hunter.", completion = "It good to see you again. I knew you not a traitor, I glad Zepik prove me right.\n\nI hear you Lich Hunter now - that pretty good! You make Harkek proud.", objectives = "Return to Frenzyheart Hill and speak to Elder Harkek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12693] = { id = 12693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolvar Faction Choice Tracker" }
quests[12694] = { id = 12694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oracle Faction Choice Tracker" }
quests[12695] = { id = 12695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Friendly Dryskin", description = "Yay! Soo-say probably worrying about us! Maybe you go back to town and tell him everything okay? Yeah, go tell Soo-say.\n\nI going grab shiny ball thing from dead lich guy - I meet you there! Go go! I meet you there!", completion = "Good to see you again! We worried when you not come back right away.\n\nJaloot beat you back - lot of energy in Jaloot, he pretty fast. He told me how you save him from lich thing. Moodle told me how you save mosswalkers too. You really nice.\n\nI hope you stay with us for while. Always something need doing.", objectives = "Return to Rainspeaker Canopy and speak to High-Oracle Soo-say.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12696] = { id = 12696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Surveillance", description = "You did a good job helping Wes with getting that flying machine back up and running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming in from the northeast.  I have a pilot ready to work for me, but I'm afraid he needs a copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing.  Tell Vic I sent you.", completion = "The professor sent you my way?  All right.", objectives = "Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12697] = { id = 12697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gothik the Harvester", description = "CHAOS, {name}! The Crusade is in a frenzy. They have diverted all forces outside of New Avalon to set up a blockade at Light's Point, east of here. They are desperately trying to strip the Havenshire Mine of all resources and load the cargo aboard the frigates they have docked on the coast.\n\nLet's stir things up a bit, shall we? Gothik the Harvester, grand necromancer of the Lich King, has graced us with his presence. He has a gift he'd like to bestow upon the Scarlet Crusade. Seek him out.", completion = "You have fought hard to invade the realm of the harvester... Wait.\n\n<Gothik looks at his notes.>\n\nMy apologies, {race}. Old habits die hard.\n\nValanar sent you, then? I trust you are somewhat competent.\n\nI do have a gift for the Scarlet dogs. One that is sure to speed up their work in the mines.", objectives = "Speak with Gothik the Harvester at Death's Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12698] = { id = 12698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift That Keeps On Giving", description = "I have come from the frozen heart of Naxxramas to feast on souls and deliver a vicious thrashing upon our sworn enemies - and I'm all out of souls.\n\nThis device I am about to give to you is a portable plague spreader. Take it east, to the Havenshire Mines, and unleash it near the Scarlet miners working inside. Use it to turn the miners into ghouls and return to me when you have a small army at your side. I have saved a special place for them in the vacuum cleaner of souls!", progress = "One small note: miners don't always become ghouls. Sometimes they turn into enraged spirits, hell-bent on killing you.", completion = "They now know that the mines are no longer safe. They will double their efforts in retreating, leaving their backs open to us!", objectives = "Gothik the Harvester at Death's Breach has given you the Gift of the Harvester to use on Scarlet Miners. Create 5 Scarlet Ghouls with the device and return the ghouls to Gothik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12699] = { id = 12699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Embarrassing Incident", description = "There's one little problem we have to solve before we head out.  You see, I can't seem to find the keys to my flying machine.\n\nI've looked pretty much everywhere for them... maybe you can give me a hand.  Only place I haven't looked yet is inside the lake.\n\nI'll even give you my very own air tank.  It's almost empty, but it's got a couple of hits left.", progress = "You find anything yet, {name}?", completion = "Excellent!", objectives = "Look for Vic's Keys inside the lake at River's Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12700] = { id = 12700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Attack Of Opportunity", description = "Only the Scarlet forces at New Avalon and Light's Point challenge us! The time to attack the Scarlet fleet at Light's Point has come.\n\nThe diversion at the mine has caused chaos amidst their ranks. They are frantically working to clear the area and return to their ships.\n\nThe time is ripe! Prince Valanar is seizing this opportunity to finish off the Scarlet fleet. Report to him at once!", completion = "You have served us well, {class}. Few of your brethren have survived our initial attack upon the Scarlet interlopers. You remain as one of the strongest.\n\n\n\nEast of us, past the Havenshire Mine, is the coast - called Light's Point by the Scarlet Crusade. A thousand soldiers stand between us and their ships. Insurmountable? Hardly the point...", objectives = "Speak with Prince Valanar at Death's Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12701] = { id = 12701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massacre At Light's Point", description = "In their haste the Crusade will make one fatal error: forgetting to check the mine cars.\n\nYou are to return to Havenshire Mine, east of here, and locate the mine car that my minions have planted near the outhouse. Climb inside the mine car and a Scarlet miner will unwittingly see to it that you are placed safely behind enemy lines.\n\nOnce aboard one of their ships, use the cannons against them! SLAUGHTER THEM ALL!\n\nCall the Scourge gryphon from the cannon when you are ready to return.", progress = "Death knights know no fear!", completion = "The entire Scarlet fleet wiped out in a matter of minutes! I will receive a commendation from the Lich King for this! All that remains of the Scarlet Crusade now are the denizens of New Avalon.\n\nI'll set the fire starters and necromancers upon Havenshire immediately. You will carry my report to the Highlord!", objectives = "Prince Valanar at Death's Breach has commanded you to slaughter 100 Scarlet Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12702] = { id = 12702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chicken Party!", description = "I bet you not guess what happen again.\n\nNope, not Goregek or chickens.\n\nOkay, I lie. Goregek let chickens out again. Dumb Goregek and rumbly belly.\n\nLet me know if you need help from any of the hunters... they around here somewhere.", progress = "Chickens not get far usually... if wasps not eat them, maybe we just let them stay on field next time.", completion = "You good at this.\n\nMaybe someday we just dump Goregek in river so you not have to do this no more.", objectives = "Capture 12 Chicken Escapees for Elder Harkek at Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12703] = { id = 12703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kartak's Rampage", description = "You the great Lich Hunter, eh? Good to have such strong Frenzyheart ally for battle. Maybe you strong enough to call Kartak even.\n\nBig battle at Kartak's Hold to southwest.  Go kill spark big-tongues until you get good bit of Oracle Blood. Bring blood to altar in Kartak's Hold to call Kartak for delicious feast of big-tongue.\n\nKartak take your body if you worthy... with Kartak's powers, you slaughter more big-tongues than even best dreams.\n\nGo kill lots, hunter!", completion = "Ritual went so easy for you!\n\nYou come back later for more killing someday, okay?", objectives = "Bring a pure sample of Oracle Blood to the Altar of Kartak to summon Kartak. With the aid of Kartak's shared powers, slaughter 50 of the nearby Sparktouched Gorlocs for Shaman Jakjek in Kartak's Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12704] = { id = 12704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appeasing the Great Rain Stone", description = "Since mosswalker been attacked I worried maybe we not good to Great Rain Stone... we maybe too greedy. We need more treasures to offer!\n\nYou good at finding shinies last time... maybe you go look more around village for shinies? You maybe need one of good Rainspeakers for help. Just tell us who.", progress = "Never enough shinies... Great Rain Stone good to us, we need be good to Great Rain Stone.", completion = "So many good shinies! You good at this.\n\nCome back for more again later, yes?", objectives = "High-Oracle Soo-say in Rainspeaker Canopy wants you to take a companion to dig up and collect 6 Shiny Treasures.\n\nBe sure to speak to High-Oracle Soo-say in Rainspeaker Canopy about securing the aid of one of your previous companions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12705] = { id = 12705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will of the Titans", description = "Puppy-men been attacking Sparktouched... we need fight or they just attack other Oracles too.\n\nYou been good friend to us, so maybe we allow you special honor. Great Ones left protector long time ago for shrines... it here still, but it not know something wrong til shrines messed with.\n\nPuppy-men down there have bad crystals for making trouble... bring a bad crystal to Lightning Shrine so Soo-holu know to help.\n\nDon't be scared if Soo-holu take your body... he very powerful, so he keep you safe.", progress = "Thank you for help dryskin. You very good to us.", completion = "Soo-holu strong, huh? I very glad he accept you to share his body for fight.\n\nHe more trusting of people he met before, so maybe come back another time to help more, yes?", objectives = "Obtain a Tainted Crystal from the wolvar near Sparktouched Haven and bring it to the Great Lightning Stone to call Soo-holu. With the aid of Soo-holu's shared powers, kill 50 of the nearby Frenzyheart wolvar, then return to Lightningcaller Soo-met near the Great Lightning Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12706] = { id = 12706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory At Death's Breach!", description = "<Prince Valanar hands you a sealed scroll.>\n\nThis is the full report of our victory at Death's Breach. You are to deliver this to Highlord Mograine - inside Acherus. I have made sure to include your heroics in the report. Mograine will undoubtedly reward you greatly for this victory, {name}.\n\nGo now!", progress = "I was certain you wouldn't make it back here in one piece, {class}. Perhaps there is more to you than I first surmised.", completion = "<Highlord Mograine reads over the report.>\n\nThe ENTIRE Scarlet fleet?\n\n<Highlord Mograine nods.>\n\nSuch power, {name}... I have not seen such a display of domination in years... Since my father wielded...\n\n\n\nIt's not important...\n\nYes, your commendation, lest I forget.", objectives = "Deliver Prince Valanar's Report to Highlord Darion Mograine in Acherus: The Ebon Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12707] = { id = 12707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wooly Justice", description = "Ahunae hear about your trip to Mam'toth Crater, mon. The children of Mam'toth are enraged and cry out for justice!\n\nFollow the avenue northeast up the steps to the next tier of Zul'Drak. On your right you will find what's left of the Altar of Mam'toth.\n\nWhen you get there, flash this Medallion of Mam'toth in front of the eyes of one of the enraged mammoths. It'll calm down for a little while, letting you hop on its back.\n\nRide it around, trampling all of the Mam'toth disciples that you can find!", completion = "Score one for the victims, mon!", objectives = "Scalper Ahunae at Zim'Torga wants you to use the Medallion of Mam'toth to calm and ride an Enraged Mammoth. You are then to trample 12 Mam'toth Disciples to death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12708] = { id = 12708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Tiki Warriors", description = "I know that you're headed up to the Zol'Maz Stronghold to the northeast, {class}. While you're there, I need you to deal with the warlord's special guardians.\n\nThe enchanted tiki warriors, as they're called, represent a very real threat. If the Drakkari were to mass produce them, we'd quickly be overrun.\n\nLet's you and I demonstrate that they're not worth the effort to create, shall we?", completion = "That should make them think twice about making more of those things. I shudder to think what it would be like to have to fight an army of those things.\n\n<The element-tamer is thoughtful for a moment.>\n\nI guess it would be just like fighting the endless waves of the Scourge.", objectives = "Element-Tamer Dagoda at Zim'Torga has asked you to destroy 12 Enchanted Tiki Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12709] = { id = 12709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexed Caches", description = "Pardon me, {name}. I'm given to understand that you might be heading northeast up to the Zol'Maz Stronghold. Such a trip presents a great opportunity for us to conclude our Drakkari goods gathering.\n\nAs I have come to know, the Drakkari warlord is extremely paranoid. He's had all of his caches at the stronghold hexed with dire magic. Rumor has it that his tiki warriors carry the cure, but who can say?\n\nIf you could find the time to acquire some of those goods, I would be most appreciative.", progress = "Perhaps you carry the caches within your pack even as we speak?", completion = "Just look at all of that!\n\nSee here, {name}. This piece you recovered vividly illustrates that the Drakkari became aware of the weakening of the land that the Scourge caused by their presence.\n\nThe warlord felt compelled to take the opportunity this presented. He pushed the prophets to kill their gods in an effort to control the power and fight back against the Lich King's forces.\n\nEither way they were doomed. They inadvertently chose to be the instrument of their own destruction!", objectives = "Chronicler To'kini at Zim'Torga has asked you to acquire 12 Zol'Maz Stronghold Caches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12710] = { id = 12710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disclosure", description = "Ya doin' well, {name}.\n\nYou be provin' dat I got an eye for talent! Now ya see why da Lich King gave me his blessing....\n\nDa time has come for me to reveal my master plan to ya, mon.\n\nNow you be seein' how we gunna sweep through da swarms of Drakkari trolls to take our rightful place in da great palace of Gundrak.\n\nTake dis scepter, mon. It be a token of my trust in ya. With it, you be able ta access my upper chamber and witness for yourself our secret weapons.", progress = "Have ya gone ta witness my creations, {name}?", completion = "So, there ya have it, mon.\n\nWe be makin' da ultimate scourge army ta serve da Lich King. He gunna be most pleased!\n\nYou keep da scepter, {name}. You gunna be needin' it ta command my army in battle....\n\nSoon!", objectives = "Drakuru in Voltarus wants you to take the teleporter to his upper chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12711] = { id = 12711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abandoned Mail", objectives = "Atop the mailbox are several illegible letters and scrolls. Useless...\n\nPerhaps you should check inside?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12712] = { id = 12712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key of Warlord Zol'Maz", description = "{name}, we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter.\n\nThe Drakkari warlord, Zol'Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast.\n\nThe warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home's gate.", progress = "I cannot stress how important it is that you acquire the warlord's key no matter the cost.", completion = "It might have been better if I hadn't asked you to bring it back here instead of heading directly to Gundrak.\n\nHowever, I think that it's best that you hear what else I have to say first.", objectives = "Har'koa at Zim'Torga has asked you to acquire the Key of Warlord Zol'Maz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12713] = { id = 12713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayal", description = "The time has come to end this charade, {name}.\n\nAs valuable as your information has been, we must bring Drakuru down and bring his project to an end before his freaks are unleashed.\n\nWe've modified your scepter for the job. When the time is right, you will be able to use it on Drakuru's Blightbloods and turn them against him. It's your only hope of defeating him.\n\nFight well.", progress = "Have you faced Drakuru in battle, {name}?", completion = "So, it is done.\n\nWe still have much to do, but our work here will be much more manageable thanks to your efforts.\n\nPlease accept this as a token of our gratitude.", objectives = "Stefan in Ebon Watch wants you to defeat Drakuru.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12714] = { id = 12714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will Of The Lich King", description = "It is the will of the Lich King that drives us onward, {name}. None are more aware of this than death knights. Our very existence is intrinsically tied to his consciousness. Surely you have heard him speak to you - invading your thoughts...\n\nCan you hear him now? Perhaps it is too early for you.\n\n<Mograine closes his eyes and nods to an unseen host.>\n\nYes, my lord. It will be done.\n\n{name}, you are to return to Death's Breach and report to Prince Valanar. The Lich King commands it!", completion = "Havenshire is ours! A thousand corpses litter the ground, patiently awaiting rebirth. We strike now at our enemy with the awakened strength of the Scourge!\n\nThe ghouls have already begun their assault upon New Avalon. Our forces have moved in behind them and taken the Crypt of Remembrance.", objectives = "Return to Death's Breach and report to Prince Valanar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12715] = { id = 12715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crypt of Remembrance", description = "The attacks upon the gates of the last Scarlet bastion have begun. Our ghouls are wearing the Crusade's front lines down while we labor to fortify our new forward base, the Crypt of Remembrance.\n\nVenture south to the crypt, which borders New Avalon, and report to my dear brother, Prince Keleseth.\n\nHe will be expecting you.\n\nPrepare yourself, {name}, for you are about to witness the next stage of Scourge warfare: DOMINATION!\n\nRide now, death knight!", completion = "Hail, {class}. I am the blood lord, Keleseth, ruler of the southeastern reaches of Northrend. The Lich King has sought to utilize my talents in ending this mortal affront to the Scourge. As with all things the Lich King asks of me, I am happy to oblige. Of course, a sea of endless souls to sate my thirst certainly sweetened the deal, don't you think?", objectives = "Report to Prince Keleseth at the Crypt of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12716] = { id = 12716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plaguebringer's Request", description = "Look at this pumpkin patch! Notice anything missing? Of course you don't, because you're a moron! Your brain was probably the first thing to die.\n\n<Noth sighs.>\n\nI have been commanded to put together a plague cauldron. You will help me.\n\nDirectly inside the gate of New Avalon is the inn. Enter the inn and steal an empty cauldron. Then go to the forge, also near the gate, and steal some iron chains. Bring those back to me along with 10 Crusader skulls. Do I need to tell you where to get those too?", progress = "Have you gathered the materials I requested?", completion = "Perfect! Now give me a moment to get things set up.", objectives = "Noth the Plaguebringer has requested that you bring him 1 Empty Cauldron, 1 Iron Chain and 10 Crusader Skulls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12717] = { id = 12717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noth's Special Brew", description = "The cauldron is ready to begin spewing its foul corruption across the land!\n\nNow, death knight, a brief lesson in plague cauldrons. The gas that the cauldron emits is deadly to the living, but empowers Scourge. As with all Scourge creations, it feeds off of death and grows stronger the longer it feeds.\n\nTake these Crusader skulls and drop them in the cauldron. You will be quite happy with the results.", progress = "The plague cauldron stands idle.", completion = "The plague cauldron jumps to life when the skulls are placed inside.\n\nAfter a few seconds some vials of dark liquid float to the top.", objectives = "Place the Pile of Crusader Skulls inside the Plague Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12718] = { id = 12718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Skulls For Brew", progress = "The plague cauldron bubbles and churns its toxic brew, spewing a thick gas all around.\n\nDo you have more Crusader skulls to place inside?", completion = "The plague cauldron jumps to life when the skulls are placed inside.\n\nAfter a few seconds, the plague cauldron grants you the dark and frothy splendor of Noth's Special Brew." }
quests[12719] = { id = 12719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere To Run And Nowhere To Hide", description = "Nothing less than total annihilation will suffice, {name}. To that end, a few hundred mindless ghouls assaulting the front gate of New Avalon will not do. We must infiltrate the inner sanctum and dispose of their officials. They must be shown that no one can escape the Scourge's grasp!\n\nMake your way to the New Avalon Town Hall, southwest of here, and assassinate the mayor. Search the building for the New Avalon registry and bring it to me.", progress = "There is nowhere to run!", completion = "The registry will tell us many things about the Scarlet insects.\n\n<Keleseth flips through the pages of the registry.>\n\nDeath rates, births, but most importantly, movement.\n\nLook here, {name}, they have already sent three vessels abroad. Let me see here... Where are they headed?\n\n\n\nWHAT? This is impossible. They sail to Northrend!\n\nBeside the coordinates are the words: \"Crimson Dawn.\"", objectives = "Prince Keleseth at the Crypt of Remembrance has ordered you to kill Mayor Quimby and recover the New Avalon Registry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12720] = { id = 12720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How To Win Friends And Influence Enemies", description = "In my travels across this world I have made several interesting discoveries. For instance, did you know that with the proper amount of encouragement one can extract all the truths that a man dares hide? As luck would have it, I happen to have some encouragement on hand.\n\n<Keleseth pulls something out of an ornately jeweled box.>\n\nThese are my \"persuaders.\" Equip them and take to the field, death knight. Apply the pointy ends to the soldiers of New Avalon. Discover the truth about this \"Crimson Dawn.\"", progress = "Use the persuaders on Scarlet Crusaders. One of them will eventually... crack.", completion = "An awakening? What nonsense do you speak, boy! What kind of fool would deliver their people into the very heart of the frozen wastes? Perhaps, though, this courier holds the answer.", objectives = "Prince Keleseth at the Crypt of Remembrance has ordered you to discover the truth about the \"Crimson Dawn.\"\n\nRemove Keleseth's Persuaders from the Ornately Jeweled Box and use them to \"persuade\" the Scarlet Crusade into talking.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12721] = { id = 12721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampage", description = "{name}, there is no time left. You must take the key and use it to unlock Akali.\n\nHe is being held in the courtyard in front of Gundrak, the capital of Zul'Drak. Akali's chains are secured by four anchor points. You must unlock each of them to set the rhino god free.\n\nGundrak is teeming with ice trolls. However, I believe that if you're careful, you should be able to slip in without too much danger.\n\nOnce you're done, please inform the witch doctor.", completion = "No!\n\nAnother god destroyed, its power stolen. And now the prophet of Akali has threatened us directly.\n\nWhen he comes, he will come for Har'koa. We cannot allow him to take her power too.\n\nWe must consult the gods once more, {name}. They will tell us what must be done.", objectives = "Har'koa at Zim'Torga has asked you to free Akali and then to inform Witch Doctor Khufu at Zim'Torga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12722] = { id = 12722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lambs To The Slaughter", description = "Most humans would have fled the moment a Scourge necropolis took up residence in their air space. Not the Scarlet Crusade!\n\nI must confess - I rather enjoy our exchanges with the Crusade. Through the years, Scourge battles against them have resulted in several of the most tragic events in human history. Yet here we stand - AGAIN - locked in battle!\n\nWe shan't deny them the pleasures of eternal servitude to the Lich King! Enter New Avalon and fulfill their death wish. Leave no survivors.", completion = "You are quite effective with that blade, {name}. Perhaps, Lich King permitting, you would be interested in becoming one of my minions? Stratholme is looking for a new mayor.", objectives = "Baron Rivendare at the Crypt of Remembrance has commanded you to slay 10 Scarlet Crusade Soldiers and 15 Citizens of New Avalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12723] = { id = 12723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Scarlet Lines", description = "I have sent Orbaz, Thassarian and Koltira behind enemy lines to search for the courier. They have set up a base of operations at the Scarlet Tavern, located at the southern end of New Avalon. The tavern is tucked away behind the two orchards, adjacent to the Chapel of the Crimson Flame. You are to make your way to the tavern and report to Orbaz Bloodbane. He will update you on their situation.", completion = "Looks like we'll let anyone into the dark order these days. When I was given the gift, things were different. Much different!\n\nAs to this courier...", objectives = "Report to Orbaz Bloodbane at the Scarlet Tavern in New Avalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12724] = { id = 12724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path Of The Righteous Crusader", description = "We haven't got a damned clue about when or where this courier is supposed to show up. None of these humans had an answer either.\n\n<Orbaz points to the Scarlet corpses strewn across the floor.>\n\nI did manage to beat something useful out of the last one. Inside Scarlet Hold they keep a schedule of all patrol routes. I want you to break into the hold and steal the schedule.\n\nThe hold is the largest building in New Avalon - northeast of here.", progress = "Tear the hold apart! The schedule is there!", completion = "<Orbaz flips through the schedule.>\n\nThese worthless cretins have been busy! Northern patrol routes, southern patrol routes, western patrol routes, eastern patrol routes, but nothing about their couriers' routes. Wait a minute. What's this? It looks like a western patrol route, coming out of Western Plaguelands? This patrol will path through here today! I'm going to need time to plan.", objectives = "Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to steal the New Avalon Patrol Schedule from the Scarlet Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12725] = { id = 12725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brothers In Death", description = "Breaking through the Scarlet lines was no easy task. We suffered many casualties during the assault and lost one of our best death knights, Koltira Deathweaver. I don't know whether he's dead or alive, but I'll be damned if we don't search for him.\n\nI last saw him being bound in irons and dragged away to the Scarlet Hold, northeast of here. Tear that keep asunder, death knight. Find Koltira!", completion = "You were foolish in coming after me. I failed. I should have been left for dead - now two of us might be killed.\n\n<Koltira shakes his head.>\n\nWe are death knights of the Scourge. This flies in the face of the dark brotherhood's covenants.\n\nThassarian, you blasted fool!", objectives = "Search for Koltira Deathweaver in the Scarlet Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12726] = { id = 12726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Wind and Water", description = "Listen to storm, yes?  The Stormwright's Shelf echoes with ancient song.... the Song of Wind and Water.\n\nThe great tempest devours the sons of typhoons and storms.  Take this drum and play his song... play Haiphoon's song.\n\nHelp him feed on wind and water so tempest can continue.", completion = "I thank you, {name}.  The great tempest will look upon us favorably thanks to you.", objectives = "Soo-nee wants you to use the Tempest Drums at the Stormwright's Shelf and help Haiphoon devour 3 Storm Revenants and 3 Aqueous Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12727] = { id = 12727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Breakout", description = "The alarms have been sounded. The High Inquisitor and his acolytes will be here soon. I'm too badly injured to be of much use, but I'll do what little I can to help.\n\nSlay the High Inquisitor and his cronies. Tear off his head and return with it to Thassarian. Vengeance will soothe his savage soul.\n\nOne more thing, {name}. If you do manage to survive and make it back to Thassarian, tell him that they're executing prisoners at the chapel. Perhaps he'll send you there to play the hero once more.", progress = "What of Koltira?", completion = "I'll feed this monster's head to the ghouls!\n\n<Thassarian tosses the head into the back room.>\n\nDid Koltira make it out?\n\n<Thassarian pauses.>\n\nI'm certain he did. Those walls can't hold him.\n\nTime for some payback.", objectives = "Slay High Inquisitor Valroth and take Valroth's Head to Thassarian at the Scarlet Tavern in New Avalon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12728] = { id = 12728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monitoring the Rift: Winterfin Cavern", description = "I need to compile my notes and prepare a presentation for my colleagues in Dalaran.\n\nWhile I do, I must ask that you visit the Winterfin Cavern to the north. You must use the Arcanometer while standing in the mouth of the cavern.\n\nReturn to me at once when you have the data. My documentation will be incomplete without it.", progress = "Have you collected the data from Winterfin Caverns yet, {name}?", completion = "Excellent, this completes my report.\n\nI'll be sure to mention your kindness to the council, {name}.", objectives = "Librarian Garren at Amber Ledge wants you to use the Arcanometer at Winterfin Caverns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12729] = { id = 12729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gods Have Spoken", description = "The gods have spoken and we must heed their wisdom.\n\nTravel north to Zim'Rhuk to destroy guardians there until they yield the unblemished heart. Travel east to the Altar of Quetz'lun and disrupt the altar wardens until you recover their gusty essence.\n\nDeliver both to Har'koa and she will combine them into that which will compel late Akali's prophet to appear.", progress = "Do you have that which is required, {name}?", completion = "Your bravery seems boundless, {name}.\n\nPlease hand me the heart and the essence, and I will fashion them into that which will compel the prophet to appear before you.", objectives = "Deliver the Unblemished Heart of the Guardian and the Gusty Essence of the Warden to Har'koa at Zim'Torga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12730] = { id = 12730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convocation at Zol'Heb", description = "You must take this instrument of convocation - of summoning - to Zol'Heb just south of Gundrak.\n\nTherein you will find a circle of power. Use the convocation to force the prophet of Akali to appear.\n\nMy heart goes out to you, {name}. We have been through much together, and you have done all that you can to not only save my life, but those of the other gods the Drakkari have destroyed.\n\nBut I fear this time we may not see each other again until the afterlife.", progress = "I can only offer you the warmth of my words and the encouragement that comes with them.\n\nTake what time you need to steel and prepare yourself, but I implore you not to take too long or the prophet will surely descend upon us.", completion = "You did it! {name}, you are the champion of Zul'Drak!\n\nWe will never be able to repay the debt that we owe to you, but the Zandalari have given into my trust a number of objects they believe you might have an interest in.\n\nPlease, I want you to have a token of our appreciation, but hurry. I sense another issue of urgency!", objectives = "Har'koa at Zim'Torga has asked you to slay the Prophet of Akali.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12732] = { id = 12732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heartblood's Strength", description = "One day, Rejek will be mighty warrior. Blood and skyfire will make Rejek strong. You see soon.\n\nRejek give you vial, you take to very top of Suntouched Pillar, far to west. Put waters there in vial.\n\nThen go to north edge of basin, to ledge north of Bonefields. You find and kill goretalon matriarch. Take heartblood.\n\nYou combine heartblood and water, bring to Rejek. Rejek drink, make strong.", progress = "Du bringst Rejek Geschenk?", completion = "Rejek dankt dir. Rejek trinkt, wird stark, nie vergisst mächtiges Geschenk von {name}.", objectives = "Bring a vial of Suntouched Heartblood to Rejek at Frenzyheart Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12733] = { id = 12733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death's Challenge", description = "Born of the Lich King's victory over Illidan Stormrage in the heart of the frozen wastes, Death's Challenge is a rite of passage that all death knights must undergo.\n\nSeek out other death knights of Acherus and challenge them to a duel. They must accept and fight until a victor emerges!\n\nGo now, {name}! Victory for the Scourge! Glory to the Lich King!", progress = "Have you completed Death's Challenge?", completion = "To the victor goes the glory, {class}! Well done! The Lich King looks favorably upon you on this day.", objectives = "Olrun the Battlecaller has ordered you to win 5 duels against other death knights.\n\nYou may choose to battle death knight initiates or players.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12734] = { id = 12734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejek: First Blood", description = "Rejek just became youngest warrior in all of Frenzyheart tribe. Father gave Rejek a mighty sword to defeat Frenzyheart enemies, but old tradition say sword need to be blooded first. Older warrior usually do that. You do this honor for Rejek?\n\nTake blade, put in corpses of all Frenzyheart foes: wasps and hardknuckles to southwest, and the big-tongues. Maybe blood blade on Mistwhispers, far to northwest near Bittertide Lake.", progress = "You blood Rejek's blade?", completion = "Rejek sees the stains of the blood of his enemies on the blade. Now Rejek has a mighty weapon for the mighty warrior he will be!", objectives = "Blood Rejek's Blade on the corpses of a Sapphire Hive Wasp, a Hardknuckle Charger, and 3 members of the Mistwhisper Tribe. You may blood the sword on either Mistwhisper Oracles or Mistwhisper Warriors. Return to Rejek at Frenzyheart Hill when your task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12735] = { id = 12735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cleansing Song", description = "Earth in Sholazar is pure.  The pillars have protected the land for centuries.\n\nWater, not as pure, it comes from outside Sholazar.... from oceans, from lakes, from rivers.  Water sometimes bring bad spirits - need to be cleansed.\n\nYou take this chime and play at Bittertide Lake, Wintergrasp River and River's Heart.  It make bad spirit angry... and then you must kill it.", completion = "Waters... cleansed.  Yes.  All is well.\n\nYou understand our way, {name}.", objectives = "Soo-nee, at the Rainspeaker Canopy, wants you to play the Cleansing Chime at Bittertide Lake, Wintergrasp River and River's Heart and slay the evil spirits that plague the waters there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
